// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Türk edebiyatı: Tanzimat'tan Cumhuriyet'e yazarlar ve eserler (orta).
const ozLiterature2Orta = <(String, String, List<String>, String)>[
  ('Tanzimat edebiyatının ilk ürünlerini veren kuşak için 1860 yılının bir dönüm noktası sayılmasının nedeni aşağıdakilerden hangisidir?', 'Türklerin çıkardığı ilk özel gazete olan Tercüman-ı Ahval\'in yayımlanmaya başlaması', ['Osmanlı\'da ilk matbaanın İbrahim Müteferrika tarafından kurulması', 'Takvim-i Vekayi\'nin devletin ilk resmî gazetesi olarak düzenli biçimde çıkarılmaya başlanması', 'Servet-i Fünun dergisinin edebiyat yayınına yönelmesi'], 'Tercüman-ı Ahval 1860\'ta Şinasi ile Agâh Efendi tarafından çıkarıldı ve yeni edebiyatın yayın organı oldu; Şair Evlenmesi de bu gazetede yayımlandı.'),
  ('Şinasi\'nin 1862\'de tek başına çıkarmaya başladığı ve daha sonra yönetimini Namık Kemal\'e bıraktığı gazete hangisidir?', 'Tasvir-i Efkâr', ['Tercüman-ı Ahval', 'Ceride-i Havadis', 'Mecmua-i Fünun'], 'Şinasi 1865\'te Paris\'e giderken Tasvir-i Efkâr\'ı Namık Kemal\'e bırakmış, Namık Kemal\'in gazeteciliği burada olgunlaşmıştır.'),
  ('Münif Paşa\'nın 1862\'de çıkardığı Mecmua-i Fünun hangi alanda bir ilk olarak anılır?', 'İlk bilim ve fikir dergisi olmasıyla', ['İlk mizah dergisi olmasıyla', 'İlk edebiyat gazetesi olmasıyla', 'Çocuklar için hazırlanan ilk dergi olmasıyla'], 'Cemiyet-i İlmiye-i Osmaniye\'nin yayın organı olan Mecmua-i Fünun, Türkçedeki ilk bilim ve fikir dergisi sayılır.'),
  ('Gazetenin Tanzimat döneminde yazı diline yaptığı etki için aşağıdakilerden hangisi söylenebilir?', 'Geniş okur kitlesine seslenme zorunluluğu dili sadeleştirmeye yöneltmiştir.', ['Gazete dili Divan inşasının süslü üslubunu daha da ağırlaştırmıştır.', 'Gazeteler yalnız Arapça yayımlandığından yazı dilimiz olan Türkçeye etkisi olmamıştır.', 'Gazete yazıları manzum olduğundan nesrin gelişimini geciktirmiştir.'], 'Halka seslenen gazete, yazarları daha anlaşılır bir dil kullanmaya ve yeni düzyazı türleri (makale, fıkra, eleştiri) üretmeye zorladı.'),
  ('Tanzimat birinci kuşak sanatçıları için aşağıdakilerden hangisi söylenemez?', '"Sanat sanat içindir" anlayışını benimsemişlerdir.', ['Eserlerinde vatan, hürriyet, adalet gibi kavramları işlemişlerdir.', 'Şiirde biçim olarak çoğunlukla Divan nazım şekillerini sürdürmüşlerdir.', 'Halkı eğitmeyi edebiyatın temel görevlerinden saymışlardır.'], 'Birinci kuşak "sanat toplum içindir" görüşündedir; sanatı sanat için yapma anlayışı daha çok ikinci kuşakta ve Servet-i Fünun\'da belirginleşir.'),
  ('İlk kuşak Tanzimat yazarlarının Fransız edebiyatından yararlanmasının yanında Divan şiirinin biçimlerini de sürdürmesi, dönemin hangi niteliğini gösterir?', 'Eski ile yeninin bir arada bulunduğu bir geçiş dönemi olduğunu', ['Batı edebiyatını tümüyle reddettiğini', 'Halk edebiyatını tek kaynak olarak benimsediğini', 'Yalnız Arap edebiyatını örnek alıp başka kaynağa yönelmediğini'], 'Tanzimat edebiyatı, yeni içeriği çoğu zaman eski kalıplarla verdiği için "geçiş dönemi" olarak nitelendirilir.'),
  ('Münif Paşa\'nın Voltaire, Fénelon ve Fontenelle\'den seçtiği diyalogları çevirdiği eser hangisidir?', 'Muhaverat-ı Hikemiye', ['Tercüme-i Manzume', 'Müntehabat-ı Eş\'ar', 'Kıssadan Hisse'], 'Muhaverat-ı Hikemiye (1859), Batı düşüncesinden yapılmış ilk düzyazı çeviri örneği sayılır.'),
  ('Şinasi\'nin La Fontaine, Racine, Lamartine gibi Fransız şairlerden manzum çevirilerini topladığı eser hangisidir?', 'Tercüme-i Manzume', ['Muhaverat-ı Hikemiye', 'Durub-ı Emsal-i Osmaniye', 'Harabat'], 'Tercüme-i Manzume (1859), Fransız şiirinden Türkçeye yapılan ilk manzum çeviri kitabıdır.'),
  ('Ahmet Vefik Paşa\'nın Molière\'den yaptığı çalışmalar için hangisi doğrudur?', 'Oyunları Türk toplumuna uyarlayarak yerli kişiler ve ortamlarla sahnelemiştir.', ['Molière\'in şiirlerini aruz ölçüsüyle gazel biçiminde çevirmiştir.', 'Molière\'in romanlarını sadeleştirerek Tercüman-ı Ahval gazetesinde uzun süre tefrika etmiştir.', 'Molière\'in hayatını anlatan ilk biyografiyi yazmıştır.'], 'Zor Nikâh, Zoraki Tabip gibi uyarlamalarda kişi adları ve yerler Türkleştirilmiştir; Ahmet Vefik Paşa Bursa\'da tiyatro da kurdurmuştur.'),
  ('Bursa valiliği sırasında bu şehirde bir tiyatro binası yaptıran ve oyunlar sahneleten Tanzimat yazarı kimdir?', 'Ahmet Vefik Paşa', ['Ziya Paşa', 'Mehmet Münif Paşa', 'Yusuf Kâmil Paşa'], 'Ahmet Vefik Paşa, Bursa\'da kurdurduğu tiyatroda Molière uyarlamalarını sahneletmiştir.'),
  ('Namık Kemal\'in Vatan yahut Silistre oyununu 1873\'te sahneleyen tiyatro hangisidir?', 'Gedikpaşa Tiyatrosu', ['Darülbedayi', 'Şehir Tiyatroları', 'Dolmabahçe Saray Tiyatrosu'], 'Güllü Agop\'un yönettiği Gedikpaşa\'daki Osmanlı Tiyatrosu oyunu sahneledi; oyunun coşkulu karşılanması Namık Kemal\'in Magosa\'ya sürülmesine yol açtı.'),
  ('Tanzimat döneminde Ermeni sanatçıların yoğun olarak yer aldığı tiyatro topluluklarının Türk oyunlarına katkısı için en doğru yargı hangisidir?', 'Türk yazarların oyunlarını sahneye taşıyarak Batılı tiyatronun yerleşmesine yardım etmişlerdir.', ['Oyunları yalnız Ermenice oynadıkları için Türk yazarlarla hiç ilişki kurmamışlardır.', 'Geleneksel ortaoyununu yasaklatarak tiyatroyu sona erdirmişlerdir.', 'Yalnız saray için oynadıklarından İstanbul halkının Batı tiyatrosuyla tanışmasını tümüyle engellemişlerdir.'], 'Güllü Agop gibi kumpanya yöneticileri Namık Kemal, Ahmet Mithat gibi yazarların oyunlarını sahneleyerek Batı tarzı tiyatronun yaygınlaşmasını sağladı.'),
  ('Tanzimat yazarlarının birçoğunun hem gazeteci hem şair hem oyun yazarı olması gibi çok yönlülük göstermeleri en çok neyle açıklanabilir?', 'Yeni türleri topluma bir an önce tanıtma isteğiyle', ['Dönemin yasalarının yazarlara tek türde yazmayı yasaklamasıyla', 'Okurların yalnız şiir okumasıyla', 'Divan geleneğinin tür çeşitliliğini zorunlu kılmasıyla'], 'Tanzimat aydınları, Batı\'dan alınan türleri hızla Türkçeye kazandırmak ve topluma yeni fikirleri her yoldan ulaştırmak istedikleri için pek çok türde ürün verdiler.'),
  ('Şair Evlenmesi\'nde gelin olarak istenen kızın yerine damada başka biriyle nikâh kıyılması üzerine kurulan olay örgüsünde damadın adı nedir?', 'Müştak Bey', ['Felatun Bey', 'Bihruz Bey', 'Rakım Efendi'], 'Oyunun kahramanı şair Müştak Bey\'dir; Felatun Bey ve Rakım Efendi Ahmet Mithat\'ın, Bihruz Bey Recaizade\'nin kişileridir.'),
  ('Şinasi\'nin Tercüman-ı Ahval\'in ilk sayısına yazdığı mukaddime Türk edebiyatında hangi bakımdan ilk sayılır?', 'Türkçe yazılmış ilk makale olması', ['İlk eleştiri kitabı olması', 'Türkçedeki ilk anı türü örneği olması', 'İlk mensur şiir olması'], 'Şinasi\'nin bu giriş yazısında halkın kendi yararını bilmesi gerektiğini savunduğu metin, Türkçedeki ilk makale kabul edilir.'),
  ('Şinasi\'nin noktalama işaretlerini yazılarında ilk kez sistemli biçimde kullanması onun hangi amacıyla en çok ilgilidir?', 'Yazıyı daha anlaşılır kılarak halkın okumasını kolaylaştırmak', ['Eserlerini yalnız seçkin okurların anlamasını sağlamak', 'Divan şiirinin ses uyumunu ve aruzun ahengini düzyazıda da korumak', 'Yazılarının kolayca kopyalanmasını engellemek'], 'Şinasi "halk için yazma" ilkesini benimsedi; noktalama ve sade dil, metnin halk tarafından anlaşılmasını amaçlıyordu.'),
  ('Şinasi\'nin şiirlerinde Divan şiirinden farklı olarak öne çıkan kavram hangisidir?', 'Akıl ve medeniyet', ['Mecazi aşk ve sevgili', 'Rindlik ve şarap', 'Tasavvufi vahdet'], 'Şinasi\'nin şiirlerinde akla dayalı düşünce, medeniyet ve kanun gibi Tanzimat fikirleri işlenir; Reşit Paşa\'ya yazdığı kasideler de bu anlayışı yansıtır.'),
  ('İntibah romanının ilk adının "Sergüzeşt-i Ali Bey" olması romanın hangi yönünü vurgular?', 'Romanın bir kişinin başından geçenleri merkeze almasını', ['Romanın tarihî bir savaşı anlatmasını', 'Romanın bir köyün hayatını konu almasını', 'Romanın baştan sona kahramanların birbirine yazdığı mektuplardan oluşmasını'], '"Sergüzeşt" başından geçenler demektir; roman Ali Bey\'in kötü bir kadına tutulup felakete sürüklenişini anlatır.'),
  ('Namık Kemal\'in Kırım hanlarından Adil Giray\'ın hayatını işleyen tarihî romanı hangisidir?', 'Cezmi', ['İntibah', 'Akif Bey', 'Gülnihal'], 'Cezmi (1880), Osmanlı-İran savaşlarında yer alan Kırım şehzadesi Adil Giray\'ı anlatan ilk tarihî roman denemesidir.'),
  ('Vatan yahut Silistre\'de sevdiği İslam Bey\'in peşinden erkek kılığına girerek cepheye giden kahraman kimdir?', 'Zekiye', ['Dilaşub', 'Kumru', 'Fitnat'], 'Zekiye, oyunda vatan ve aşk duygularını birleştiren kadın kahramandır.'),
  ('Namık Kemal\'in Celâleddin Harzemşah oyununa yazdığı ve tiyatro ile roman hakkındaki görüşlerini açıkladığı önsözün adı nedir?', 'Mukaddime-i Celal', ['Tahrib-i Harabat', 'Takip', 'İrfan Paşa\'ya Mektup'], 'Mukaddime-i Celal\'de Namık Kemal, Divan edebiyatını eleştirir; roman ve tiyatronun önemini, yeni edebiyatın ilkelerini anlatır.'),
  ('Namık Kemal\'in görmeden ve istemeden evlendirilmenin yol açtığı acıları işlediği oyunu hangisidir?', 'Zavallı Çocuk', ['Kara Belâ', 'Celâleddin Harzemşah', 'Akif Bey'], 'Zavallı Çocuk\'ta Şefika\'nın zorla yaşlı bir adamla evlendirilmek istenmesi ve bunun dramla sonuçlanması anlatılır.'),
  ('Namık Kemal\'in İrfan Paşa\'ya yazdığı mektupta Divan edebiyatına yönelttiği eleştirinin özü nedir?', 'Divan şiirinin gerçeklikten uzak, abartılı ve hayali olduğu', ['Divan şiirinin fazla sade bir dil kullandığı', 'Divan şairlerinin toplumsal konulara çok yer verdiği', 'Divan şiirinin hece ölçüsüyle yazıldığı ve bu yüzden ahenkten yoksun kaldığı'], 'Namık Kemal bu mektupta Divan şiirini gerçeklikten kopuk, aşırı süslü ve mübalağalı bulduğu için eleştirir.'),
  ('Namık Kemal\'in 1872\'de çıkardığı ve kapatılmasının ardından sürgüne gönderilmesine zemin hazırlayan gazete hangisidir?', 'İbret', ['Hürriyet', 'Tercüman-ı Ahval', 'Ceride-i Havadis'], 'İbret gazetesinde yayımlanan sert yazılar nedeniyle gazete defalarca kapatıldı; Namık Kemal\'in Gelibolu\'ya mutasarrıf olarak uzaklaştırılmasında da rol oynadı.'),
  ('Namık Kemal\'in tiyatroya bakışı için aşağıdakilerden hangisi en doğrudur?', 'Tiyatroyu halkı eğiten ve yönlendiren bir "eğlenceli eğitim" aracı olarak görmüştür.', ['Tiyatroyu yalnız sarayın eğlencesi olarak değerlendirmiştir.', 'Tiyatronun ahlaka zarar verdiğini düşünüp karşı çıkmıştır.', 'Yalnız klasik Yunan trajedilerinin çevrilmesini isteyip yerli oyun yazılmasına karşı çıkmıştır.'], 'Namık Kemal, tiyatroyu "eğlencelerin en faydalısı" sayar ve halka vatan sevgisi aşılamanın aracı olarak görür.'),
  ('Ziya Paşa\'nın 1868\'de Hürriyet gazetesinde yayımlanan "Şiir ve İnşa" makalesinde savunduğu görüş hangisidir?', 'Gerçek millî şiirin Divan şiiri değil, halk şiiri olduğu', ['Türk şiirinin yalnız Fars şiirini örnek alarak gelişmesi gerektiği', 'Şiirin hece ölçüsünü tamamen bırakması gerektiği', 'Divan şiirinin Türk şiirinin en yüksek örneği olduğu'], 'Ziya Paşa bu makalede halk şiirini ve halk dilini gerçek millî edebiyat sayar; Divan şiirinin yabancı kaynaklı olduğunu söyler.'),
  ('Ziya Paşa\'nın "Şiir ve İnşa" makalesi ile Harabat\'ın önsözü karşılaştırıldığında ortaya çıkan durum nedir?', 'Halk şiirini öven yazar, daha sonra Divan şiirini övüp halk şiirini küçümsemiştir.', ['İki metinde de halk şiirini savunan aynı görüşü hiç değiştirmeden sürdürmüştür.', 'Önce Divan şiirini savunmuş, sonra hiç ilgilenmemiştir.', 'İki metinde de yalnız Batı şiirini övmüştür.'], '"Şiir ve İnşa"da halk şiirini savunan Ziya Paşa, Harabat önsözünde Divan şiirini yüceltmiştir; bu çelişki ona "tezatlar adamı" denmesine yol açmıştır.'),
  ('Ziya Paşa\'nın en tanınmış iki şiiri olan Terkib-i Bend ve Terci-i Bend\'in ortak özelliği hangisidir?', 'Bentlerden oluşan ve hikmetli, öğretici söyleyişler içeren uzun manzumeler olmaları', ['Hece ölçüsüyle dörtlükler hâlinde yazılmış koşmalar olmaları', 'Ölçü ve uyak kullanılmadan mensur şiir biçiminde yazılmış olmaları', 'Aşk konulu kısa gazeller olmaları'], 'Bu iki şiir bentlerden oluşur; Terkib-i Bend\'de toplum ve devlet düzenine eleştiriler, Terci-i Bend\'de ise isyan ve teslimiyet arasında gidip gelen felsefi sorgulamalar vardır.'),
  ('Ziya Paşa\'nın Sadrazam Âli Paşa\'yı hicvettiği, övgü kalıbını tersine kullanarak yazdığı eseri hangisidir?', 'Zafername', ['Harabat', 'Rüya', 'Defter-i Amal'], 'Zafername, Âli Paşa\'yı övüyormuş gibi görünürken alaya alan, kaside biçimindeki ünlü bir hicviyedir.'),
  ('Ziya Paşa\'nın çocukluk anılarını anlattığı ve Türk edebiyatında anı türünün ilk örneklerinden sayılan eser hangisidir?', 'Defter-i Amal', ['Zafername', 'Evrak-ı Perişan', 'Ömrüm'], 'Defter-i Amal, Ziya Paşa\'nın çocukluğunu ve eğitimini anlattığı anı eseridir; Ömrüm ise Muallim Naci\'nindir.'),
  ('Ziya Paşa\'nın Rousseau\'dan çevirdiği eser hangisidir?', 'Emil', ['Telemak', 'Atala', 'Sefiller'], 'Ziya Paşa Rousseau\'nun eğitim üzerine yazdığı Emile\'i Türkçeye çevirmiştir; ayrıca Endülüs Tarihi ve Engizisyon Tarihi gibi çevirileri vardır.'),
  ('Ziya Paşa\'nın şiirde Tanzimat\'ın diğer yazarlarından ayrıldığı nokta için en uygun yargı hangisidir?', 'Biçimde Divan geleneğine en bağlı kalan Tanzimat şairi olması', ['Batı nazım biçimlerini ilk kez Türk şiirine getirmesi', 'Şiirlerini yalnız halk diliyle yazması', 'Romantik doğa şiirinin Türk edebiyatındaki ilk ve en güçlü öncüsü olması'], 'Ziya Paşa, vatan ve hürriyet gibi kavramlara yer verse de şiirinde Divan geleneğine en çok bağlı kalan Tanzimat sanatçısıdır.'),
  ('Ahmet Mithat Efendi\'nin Türk edebiyatında Batılı anlamdaki hikâyenin ilk örnekleri sayılan eseri hangisidir?', 'Letaif-i Rivayat', ['Müşahedat', 'Henüz On Yedi Yaşında', 'Avrupa\'da Bir Cevelan'], 'Letaif-i Rivayat\'taki uzun hikâyeler, Batılı anlamda hikâyenin ilk örnekleri olarak kabul edilir; daha önce yayımladığı Kıssadan Hisse ise kısa ve öğretici anlatılardır.'),
  ('Ahmet Mithat\'ın Avrupa\'ya yaptığı yolculuğu anlattığı gezi kitabı hangisidir?', 'Avrupa\'da Bir Cevelan', ['Hac Yolunda', 'Frankfurt Seyahatnamesi', 'Avrupa Mektupları'], 'Ahmet Mithat 1889\'da Stockholm\'deki Müsteşrikler Kongresi\'ne katıldığı yolculuğu Avrupa\'da Bir Cevelan\'da anlattı; Avrupa Mektupları ve Hac Yolunda Cenap Şahabettin\'indir.'),
  ('Ahmet Mithat\'ın 1878\'de çıkarmaya başladığı ve uzun yıllar sürdürdüğü gazete hangisidir?', 'Tercüman-ı Hakikat', ['Tasvir-i Efkâr', 'Muhbir', 'Ceride-i Havadis'], 'Tercüman-ı Hakikat, Ahmet Mithat\'ın gazetesidir; edebiyat sayfasını Muallim Naci yönetmiştir.'),
  ('1873\'te Namık Kemal ve arkadaşlarıyla aynı dönemde sürgüne gönderilen Ahmet Mithat\'ın sürgün yeri neresidir?', 'Rodos', ['Magosa', 'Akka', 'Sinop'], 'Ahmet Mithat Rodos\'a sürülmüş, sürgün yıllarında da yazmayı sürdürmüştür; Namık Kemal ise aynı yıl Magosa\'ya gönderilmişti.'),
  ('Şemsettin Sami\'nin Türkçenin sözlük çalışmaları içinde önemli bir yer tutan eseri hangisidir?', 'Kamus-ı Türki', ['Lehçe-i Osmani', 'Lügat-ı Naci', 'Talim-i Edebiyat ve Belagat-ı Osmaniye'], 'Kamus-ı Türki (1901), Şemsettin Sami\'nin Türkçe sözlüğüdür; Kamusü\'l-a\'lam ise onun altı ciltlik ansiklopedisidir.'),
  ('Şemsettin Sami\'nin dil konusundaki görüşleri için aşağıdakilerden hangisi doğrudur?', '"Osmanlıca" yerine "Türkçe" adının kullanılması gerektiğini savunmuştur.', ['Türkçenin bütünüyle Arap alfabesinin kurallarına göre Arapça kelimelerle yazılması gerektiğini ileri sürmüştür.', 'Türkçede yabancı kelimelerin çoğaltılmasını istemiştir.', 'Yazı dilinin halk dilinden uzak tutulmasını önermiştir.'], 'Şemsettin Sami dilimizin adının "Türkçe" olduğunu savunmuş, sözlüğüne de Kamus-ı Türki adını vermiştir.'),
  ('Tanzimat ikinci kuşağının sanat anlayışı için aşağıdaki yargılardan hangisi doğrudur?', 'Sanatın toplum için değil, sanat için yapılması gerektiğini benimsemeye başlamışlardır.', ['Eserlerinde yalnız siyasi propagandaya yer verip bireysel duyguları bütünüyle dışarıda bırakmışlardır.', 'Romanda natüralizmi bütün kurallarıyla uygulamışlardır.', 'Hece ölçüsünü aruzun yerine tamamen yerleştirmişlerdir.'], 'İkinci kuşak, II. Abdülhamit döneminin baskıcı ortamında toplumsal konulardan uzaklaşıp bireyselliğe ve "sanat için sanat" anlayışına yöneldi.'),
  ('Tanzimat ikinci kuşağının "her şey şiirin konusu olabilir" görüşü hangi yeniliği getirmiştir?', 'Şiirde doğa, ölüm, sıradan nesneler gibi yeni konulara yer verilmesini', ['Şiirde yalnız hükümdarların övülmesini', 'Şiirde aruzun tamamen terk edilmesini', 'Şiirin yalnız dinî ve tasavvufi konularla sınırlandırılmasını istemelerini'], 'Recaizade ve Abdülhak Hamit, güzel olan her şeyin şiire girebileceğini savunarak şiirin konu alanını genişletti.'),
  ('Araba Sevdası\'nda Bihruz Bey\'e Periveş\'in öldüğünü söyleyerek olayların gülünç bir yöne gitmesine neden olan yalancı kişi kimdir?', 'Keşfi Bey', ['Hikmet Efendi', 'Behlül Bey', 'Batak Efendi'], 'Keşfi Bey\'in uydurmaları üzerine Bihruz Bey, yaşayan Periveş\'in yasını tutar; bu durum romanın gülmece yönünü güçlendirir.'),
  ('Araba Sevdası\'nın Türk edebiyatındaki yeri için en yaygın kabul gören değerlendirme hangisidir?', 'Gerçekçiliğin ilk başarılı örneklerinden biri olması', ['İlk tarihî roman olması', 'Natüralizmin Türk edebiyatındaki en olgun ve kusursuz örneği olması', 'İlk köy romanı olması'], 'Araba Sevdası (yazılışı 1889, kitap 1896), gerçekçi tutum, konuşma dilinin kullanımı ve tip yaratma başarısıyla ilk realist roman denemelerinden sayılır.'),
  ('Araba Sevdası\'nda kişilerin konuşmalarının kendi ağızlarına ve yetişme biçimlerine uygun verilmesi romanın hangi niteliğini güçlendirir?', 'Gerçekçiliğini', ['Tarihî atmosferini', 'Fantastik yönünü', 'Destansı havasını'], 'Kişilerin kendi dil ve üsluplarıyla konuşturulması gerçekçi romanın önemli bir tekniğidir; Recaizade bunu Bihruz Bey\'in bozuk Fransızcası ve halk ağzıyla başarıyla uygular.'),
  ('Recaizade Mahmut Ekrem\'in Batılı anlayışla yazılmış bir edebiyat bilgisi kitabı olarak öne çıkan eseri hangisidir?', 'Talim-i Edebiyat', ['Takdir-i Elhan', 'Zemzeme', 'Nağme-i Seher-i Edebiyat'], 'Talim-i Edebiyat, Mekteb-i Mülkiye\'de okuttuğu dersler üzerine kurulmuş, Batı ve Doğu edebiyatından örnekler içeren bir edebiyat kuramı kitabıdır.'),
  ('Recaizade Mahmut Ekrem\'in genç yaşta ölen oğluna yazdığı şiirlerin büyük bölümünü topladığı eser hangisidir?', 'Pejmürde', ['Zemzeme', 'Nağme-i Seher', 'Yadigâr-ı Şebab'], 'Recaizade, oğlu Nijad\'ın ölümü üzerine yazdığı acılı şiirlerin önemli bir kısmını Pejmürde\'de toplamıştır; Nijad Ekrem adlı ayrı bir eseri de vardır.'),
  ('Recaizade Mahmut Ekrem\'in Servet-i Fünun topluluğu ile ilişkisi için hangisi doğrudur?', 'Genç şairlere yol gösterip onları Servet-i Fünun dergisi etrafında toplamıştır.', ['Topluluğun en sert eleştirmeni olarak dergiye karşı yazılar yazmıştır.', 'Topluluk dağıldıktan sonra derginin sahibi olarak onu yeniden yayımlamaya başlamıştır.', 'Toplulukla hiçbir bağı olmamış, yalnız Fecr-i Âti\'yi desteklemiştir.'], 'Recaizade, Tevfik Fikret\'i derginin başına getirilmesinde etkili olmuş, Servet-i Fünun\'un hazırlayıcısı ve hamisi sayılmıştır.'),
  ('Muallim Naci\'nin Recaizade\'nin Zemzeme adlı eserine karşı yazdığı eserin adı nedir?', 'Demdeme', ['Takdir-i Elhan', 'Tahrib-i Harabat', 'Ateşpare'], 'Zemzeme\'nin önsözündeki görüşlere karşı Naci, Demdeme\'yi yazdı; bu tartışma eski-yeni çatışmasının önemli halkalarındandır.'),
  ('Recaizade Mahmut Ekrem\'in Muallim Naci\'nin şiirlerini eleştirdiği ve yeni şiiri savunduğu eser hangisidir?', 'Takdir-i Elhan', ['Talim-i Edebiyat', 'Demdeme', 'Muhsin Bey'], 'Takdir-i Elhan (1886), eski şiir anlayışını eleştirip yeni şiiri savunan bir eleştiri kitabıdır.'),
  ('Recaizade Mahmut Ekrem\'in tiyatro alanındaki eserleri arasında yer alan komedi hangisidir?', 'Çok Bilen Çok Yanılır', ['Vatan yahut Silistre', 'Akif Bey', 'Zavallı Çocuk'], 'Çok Bilen Çok Yanılır, Recaizade\'nin komedi türündeki oyunudur; Afife Anjelik ve Vuslat da onun oyunlarıdır.'),
  ('Abdülhak Hamit\'in tiyatroları için aşağıdakilerden hangisi doğrudur?', 'Çoğu sahnelenmekten çok okunmak için yazılmış, konularını sıklıkla tarihten almıştır.', ['Tamamı tek perdelik, gündelik hayattan alınmış töre komedileridir.', 'Yalnız Anadolu köy hayatını konu alan, gözleme dayalı gerçekçi dramlardır ve kısa tutulmuştur.', 'Tümü geleneksel ortaoyunu kalıbında yazılmıştır.'], 'Hamit\'in oyunları Shakespeare etkisinde, çoğunlukla tarihî konulu, uzun ve sahne tekniği bakımından oynanması güç eserlerdir.'),
  ('Abdülhak Hamit\'in Büyük İskender\'in Hindistan seferi sırasındaki olayları işlediği oyunu hangisidir?', 'Eşber', ['Tezer', 'Nesteren', 'İbn Musa'], 'Eşber, İskender\'e karşı direnen bir Hint hükümdarını anlatan tarihî bir oyundur.'),
  ('Abdülhak Hamit\'in uzun yıllar diplomat olarak çalışması eserlerine en çok hangi yönden yansımıştır?', 'Yabancı ülkelerden ve kültürlerden konular, mekânlar seçmesi', ['Eserlerinde yalnız doğduğu İstanbul\'un semtlerini ve yalılarını anlatması', 'Yalnız Divan şiirinin konularını sürdürmesi', 'Eserlerini Fransızca yazması'], 'Paris, Londra, Bombay gibi yerlerde görev yapan Hamit; Hindistan, İngiltere, Endülüs gibi mekânları eserlerine taşımıştır.'),
  ('Sergüzeşt\'in Türk romanının gelişimindeki yeri için en uygun yorum hangisidir?', 'Romantizmden realizme geçişin ilk örneklerinden biridir.', ['Natüralizmin ilk ve tam örneğidir.', 'Sembolizmin roman alanındaki tek örneğidir.', 'Klasisizmin kurallarını romana eksiksiz uygulayan ilk eserdir.'], 'Romantik bir konuyu işlemesine karşın gerçekçi gözlem ve tasvirler içeren Sergüzeşt, romantizmden realizme geçiş eseri kabul edilir.'),
  ('Sami Paşazade Sezai\'nin Batılı anlamda ilk realist hikâyeler sayılan eseri hangisidir?', 'Küçük Şeyler', ['Letaif-i Rivayat', 'Bir Serencam', 'Memleket Hikâyeleri'], 'Küçük Şeyler (1892), gündelik hayattan alınmış küçük olayları gerçekçi bir gözlemle anlatan hikâyelerdir.'),
  ('Sami Paşazade Sezai\'nin tiyatro alanındaki eseri hangisidir?', 'Şîr', ['Besa', 'Gave', 'Akif Bey'], 'Şîr, Sezai\'nin tarihî bir oyunudur; Besa ve Gave Şemsettin Sami\'nin, Akif Bey Namık Kemal\'indir.'),
  ('Karabibik\'in geçtiği yer için hangisi doğrudur?', 'Antalya yöresinde bir köy', ['Erzurum yöresinde bir yayla', 'Trakya\'da bir kasaba', 'Konya ovasında bir çiftlik'], 'Nabizade Nazım Antalya\'daki görevi sırasında edindiği gözlemleri Karabibik\'te kullanmıştır.'),
  ('Nabizade Nazım\'ın Türk edebiyatında ilk psikolojik roman denemesi sayılan eseri hangisidir?', 'Zehra', ['Eylül', 'Muhadarat', 'Karabibik'], 'Zehra (1896), kıskançlığın bir kadını nasıl yıkıma sürüklediğini anlatan ilk psikolojik roman denemesidir; Eylül ise Servet-i Fünun\'da yazılmış ilk olgun psikolojik romandır.'),
  ('Muallim Naci\'nin çocukluk yıllarını anlattığı otobiyografik eser hangisidir?', 'Ömer\'in Çocukluğu', ['Defter-i Amal', 'Anamın Kitabı', 'Gençlik ve Edebiyat Hatıraları'], 'Ömer\'in Çocukluğu, Muallim Naci\'nin kendi çocukluğunu anlattığı eserdir; asıl adı Ömer olan Naci bu adı kitabına vermiştir.'),
  ('Muallim Naci\'nin şiir anlayışı için en doğru yargı hangisidir?', 'Divan şiirinin dil ve biçim geleneğini sürdürmekle birlikte yeni konulara da kapı açmıştır.', ['Şiirlerinin tamamını hece ölçüsüyle, halk ağzıyla ve koşma biçiminde yazarak Divan geleneğinden bütünüyle kopmuştur.', 'Batı\'nın sembolist şiirini Türkçeye ilk getiren şairdir.', 'Şiirde ölçü ve uyağı tamamen reddetmiştir.'], 'Naci eski edebiyatın savunucusu olarak bilinse de doğa ve gündelik hayata dair yeni temalı şiirler de yazmıştır.'),
  ('Fatma Aliye Hanım\'ın Ahmet Mithat Efendi ile birlikte yazdığı ve kapağında "Bir Kadın" imzası bulunan roman hangisidir?', 'Hayal ve Hakikat', ['Udi', 'Refet', 'Levayıh-ı Hayat ve Enin'], 'Hayal ve Hakikat, ortak yazılmış bir romandır; Fatma Aliye adını kullanmadan "Bir Kadın" imzasıyla yer almıştır.'),
  ('Fatma Aliye Hanım\'ın tarih ve hukuk alanındaki eserleriyle tanınan ünlü babası kimdir?', 'Ahmet Cevdet Paşa', ['Ahmet Vefik Paşa', 'Mehmet Münif Paşa', 'Mithat Paşa'], 'Fatma Aliye, Mecelle\'nin hazırlanmasına öncülük eden ve Tarih-i Cevdet\'in yazarı Ahmet Cevdet Paşa\'nın kızıdır.'),
  ('Fatma Aliye Hanım\'ın romanlarında ağırlıklı olarak ele aldığı konu hangisidir?', 'Toplumda kadının yeri, eğitimi ve evlilik sorunları', ['Balkan Savaşları\'ndaki cephe hayatı', 'Anadolu köylerindeki toprak kavgaları', 'Tarihî fetihler, akıncılar ve kahramanlık destanları'], 'Fatma Aliye kadının eğitimi, evlilik, aile hayatı gibi konuları işlemiş; Udi\'de bir kadının hayatını müzik çevresiyle birlikte anlatmıştır.'),
  ('Mizancı Murat\'ın Turfanda mı Yoksa Turfa mı? romanında idealist kahraman Mansur Bey\'in temsil ettiği düşünce hangisidir?', 'Devleti kurtarmak için toplumda köklü bir yenileşme yapılması gerektiği', ['Köy hayatının şehir hayatından üstün olduğu', 'Batılılaşmanın tamamen terk edilip eski kurumlara dönülmesi gerektiği düşüncesi', 'Aşkın her şeyin önünde geldiği'], 'Mansur Bey, Avrupa\'da eğitim görmüş, memleketi kurtarmak için çalışan idealist bir tiptir; ancak çevresince anlaşılamaz.'),
  ('Aşağıdakilerden hangisi Tanzimat romanının genel özelliklerinden biri değildir?', 'Anlatıcının olayların dışında kalıp hiç yorum yapmaması', ['Yazarın araya girip okura bilgi vermesi', 'Tesadüflere sıkça başvurulması', 'Toplumsal sorunların ve aile hayatının ele alınması'], 'Tanzimat yazarları sıkça araya girer; anlatıcının tamamen görünmez kaldığı nesnel anlatım daha sonra, Servet-i Fünun\'da gelişir.'),
  ('Tanzimat romanında mekân olarak en sık İstanbul\'un seçilmesi ve Anadolu\'nun çok az yer alması nasıl yorumlanabilir?', 'Yazarların çoğunun İstanbul\'da yaşayıp şehir çevresini gözlemlemesinin sonucudur.', ['Anadolu\'yu anlatmak yasaklandığı için zorunlu bir tercihtir.', 'Okurların İstanbul dışını hiç tanımak istememesindendir.', 'Divan şiirinin İstanbul dışını anlatmayı uygunsuz saymasına duyulan bağlılığın ve geleneğin sonucudur.'], 'Tanzimat yazarları büyük ölçüde İstanbullu aydınlardı; Anadolu\'nun romana yaygın biçimde girmesi Millî Edebiyat döneminde gerçekleşti. Karabibik bu bakımdan istisnadır.'),
  ('Tanzimat döneminde "macera romanı" türünde yazılmış, kahramanının denizlerde ve uzak ülkelerde serüvenler yaşadığı roman hangisidir?', 'Hasan Mellah', ['Cezmi', 'Zehra', 'Felatun Bey ile Rakım Efendi'], 'Ahmet Mithat\'ın Hasan Mellah\'ı, Monte Kristo etkisi taşıyan, serüvenlerle dolu bir macera romanıdır.'),
  ('Hüseyin Rahmi Gürpınar\'ın kendini Servet-i Fünun topluluğuna katmamasına karşın o dönemde yazması, onun edebiyat tarihindeki konumunu nasıl belirler?', 'Topluluk dışında kalmış bağımsız bir yazar olarak değerlendirilir.', ['Servet-i Fünun\'un kurucusu sayılır.', 'Fecr-i Âti topluluğunun kurucu başkanı olarak kabul edilir.', 'Millî Edebiyat\'ın öncüsü olarak sınıflandırılır.'], 'Hüseyin Rahmi, Servet-i Fünun yıllarında yazmasına karşın topluluğa katılmamış, kendine özgü çizgisini korumuştur.'),
  ('Hüseyin Rahmi Gürpınar\'ın bir konağa çocukların eğitimi için alınan Fransız Anjel\'in çevresinde gelişen olayları anlattığı romanı hangisidir?', 'Mürebbiye', ['Metres', 'İffet', 'Kokotlar Mektebi'], 'Mürebbiye\'de Anjel adlı Fransız kadın, mürebbiyelik bahanesiyle girdiği konakta aileyi ahlaki çöküntüye sürükler.'),
  ('Hüseyin Rahmi Gürpınar\'ın uzun yıllar yaşadığı ve evinin bugün müze olarak korunduğu yer neresidir?', 'Heybeliada', ['Büyükada', 'Kandilli', 'Rumelihisarı'], 'Hüseyin Rahmi ömrünün son kırk yılı kadarını Heybeliada\'daki köşkünde geçirmiştir; Rumelihisarı ise Tevfik Fikret\'in Aşiyan\'ının bulunduğu yerdir.'),
  ('Ahmet Mithat Efendi\'nin Servet-i Fünun yazarlarını kapalı ve anlaşılmaz bir dil kullanmakla suçladığı 1897 tarihli makalesinin adı nedir?', 'Dekadanlar', ['Edebiyat ve Hukuk', 'Yeni Lisan', 'Şiir ve İnşa'], 'Dekadanlar makalesi Sabah gazetesinde yayımlanmış, Servet-i Fünuncularla geniş bir tartışma başlatmıştır.'),
  ('Servet-i Fünun dergisini 1891\'de kuran kişi kimdir?', 'Ahmet İhsan Tokgöz', ['Tevfik Fikret', 'Recaizade Mahmut Ekrem', 'Hüseyin Cahit Yalçın'], 'Ahmet İhsan Tokgöz\'ün kurduğu dergi önce bilim ve haber ağırlıklıydı; 1896\'da Tevfik Fikret\'in yazı işlerine gelmesiyle edebiyat dergisine dönüştü.'),
  ('Servet-i Fünun dergisinin bir edebiyat topluluğunun yayın organına dönüşmesi hangi gelişmeyle başlamıştır?', 'Tevfik Fikret\'in 1896\'da yazı işleri müdürü olması', ['Derginin Selanik\'e taşınması', 'Namık Kemal\'in dergiye yazmaya başlaması', 'Derginin adının Genç Kalemler olarak değiştirilmesi'], 'Recaizade\'nin önerisiyle Tevfik Fikret\'in derginin başına geçmesi, Edebiyat-ı Cedide topluluğunun doğuşu sayılır.'),
  ('Servet-i Fünun sanatçılarının eserlerinde sıkça görülen "kaçış" (gerçeklerden kaçma) temasının en önemli nedeni olarak hangisi gösterilir?', 'II. Abdülhamit döneminin baskıcı siyasi ortamı', ['Balkan Savaşları\'nda Rumeli\'de yaşanan ağır yenilgiler', 'Cumhuriyet\'in ilanının getirdiği yenilikler', 'Kurtuluş Savaşı\'nın yol açtığı yıkım'], 'Sansür ve baskı ortamında sanatçılar toplumsal konulardan uzaklaşıp hayal dünyasına ve bireysel duygulara yöneldi; Yeni Zelanda\'ya göç düşüncesi bunun simgesidir.'),
  ('Tevfik Fikret ve Hüseyin Cahit\'in Servet-i Fünun yıllarında bir süre gerçekleştirmeyi düşündükleri ama başaramadıkları plan hangisidir?', 'Yeni Zelanda\'ya göç edip orada bir koloni kurmak', ['Paris\'te Türkçe bir dergi çıkarmak', 'Anadolu\'da bir köy okulu açıp öğretmenlik yapmak üzere yola çıkmak', 'İstanbul\'da bir tiyatro kurmak'], 'Baskıdan bunalan topluluk üyeleri Yeni Zelanda\'ya yerleşmeyi tasarlamış, ancak bu düşünce gerçekleşmemiştir.'),
  ('Tevfik Fikret\'in Türk şiirine kazandırdığı, aruzun farklı kalıplarını bir arada kullanmaya ve dizeleri istenen uzunlukta yazmaya imkân veren biçim hangisidir?', 'Serbest müstezat', ['Sone', 'Terza rima', 'Murabba-ı mütekerrir'], 'Fikret ve arkadaşları, Divan\'daki müstezadı serbestleştirerek farklı uzunlukta dizelerin kullanılabildiği serbest müstezadı geliştirdiler.'),
  ('Servet-i Fünun şiirinde anlamın bir dizede tamamlanmayıp sonraki dizeye taşması hangi kavramla adlandırılır?', 'Anjanbman', ['Redif', 'Mazmun', 'Tecahül-i arif'], 'Servet-i Fünun şairleri Divan şiirindeki beyit bütünlüğünü bozarak anjanbman (cümlenin bir sonraki dizeye geçmesi) tekniğini kullandılar.'),
  ('Servet-i Fünun şiirinin Divan şiirinden ayrılan yönleri arasında aşağıdakilerden hangisi yer almaz?', 'Aruz ölçüsünün kullanılması', ['Beyit bütünlüğünün bozulması', 'Batılı nazım biçimlerinin (sone, terza rima) denenmesi', 'Şiirin bütün olarak düşünülmesi'], 'Servet-i Fünuncular aruzu sürdürmüşlerdir; bu yönden Divan şiiriyle ortaktırlar. Diğer üç özellik ise getirdikleri yeniliklerdir.'),
  ('Servet-i Fünun romanının Tanzimat romanına göre teknik olarak ilerlemesini en iyi gösteren özellik hangisidir?', 'Yazarın araya girmeden, nesnel bir anlatımı tercih etmesi', ['Olayların tesadüflerle ilerlemesi', 'Kişilerin iyi-kötü diye ayrılması', 'Okura sık sık öğüt verilmesi ve ahlak dersi çıkarılması'], 'Servet-i Fünun romanında yazar araya girmez; kişilerin ruh hâlleri ve çevre ayrıntılı tasvir edilir. Diğer üç seçenek Tanzimat romanının kusurlarıdır.'),
  ('Tevfik Fikret\'in şiirleri genellikle iki döneme ayrılır. Bu iki döneme ilişkin en doğru eşleştirme hangisidir?', '1901 öncesi bireysel şiirler; 1901 sonrası toplumsal şiirler', ['1901 öncesi toplumsal şiirler; 1901 sonrası aşk şiirleri', '1901 öncesi hece şiirleri; 1901 sonrası aruz şiirleri', '1901 öncesi dinî ve tasavvufi şiirler; 1901 sonrası doğa şiirleri'], 'Servet-i Fünun\'un kapanmasına kadar daha çok bireysel şiirler yazan Fikret, 1901\'den sonra toplumsal ve siyasi konulara yönelir.'),
  ('Tevfik Fikret\'in II. Meşrutiyet\'ten sonra müdürlüğünü yaptığı okul hangisidir?', 'Galatasaray Sultanisi', ['Darüşşafaka', 'Mekteb-i Mülkiye-i Şahane', 'Robert Kolej'], 'Fikret 1909\'da Galatasaray Sultanisi\'ne müdür oldu; daha önce Robert Kolej\'de Türkçe öğretmenliği yapmıştı.'),
  ('Tevfik Fikret\'in devlet malını yağmalayan yöneticileri ve çıkarcıları "yağma sofrası" benzetmesiyle hicvettiği şiiri hangisidir?', 'Han-ı Yağma', ['Sis', 'Doksan Beşe Doğru', 'Haluk\'un Vedaı'], 'Han-ı Yağma\'da devletin varlıklarını yağmalayanlar bir sofraya üşüşmüş açgözlüler olarak tasvir edilir.'),
  ('Cenap Şahabettin\'in Fransız sembolistlerinden etkilenerek benimsediği şiir anlayışı hangisidir?', 'Şiirde anlamdan çok müziğe ve çağrışıma önem vermek', ['Şiiri halkı eğitmenin aracı olarak görmek ve öğüt vermek', 'Şiiri hece ölçüsüyle ve halk deyişleriyle yazmak', 'Şiiri tarihî olayları anlatan uzun destanlar olarak kurmak'], 'Cenap Şahabettin, şiirde ahenk ve müzikaliteye önem verir; anlamın kolayca anlaşılmasını şart görmez.'),
  ('Cenap Şahabettin\'in hacca giden bir gemide karantina doktoru olarak bulunduğu yolculuğu anlattığı gezi kitabı hangisidir?', 'Hac Yolunda', ['Afak-ı Irak', 'Avrupa Mektupları', 'Avrupa\'da Bir Cevelan'], 'Hac Yolunda (1909), Cenap\'ın Cidde ve Hicaz yolculuğunu anlatır; Afak-ı Irak ise Irak\'a yaptığı yolculuğun ürünüdür.'),
  ('Cenap Şahabettin\'in özlü sözlerini (aforizmalarını) içeren eseri hangisidir?', 'Tiryaki Sözleri', ['Evrak-ı Eyyam', 'Tâmat', 'Nesr-i Harb Nesr-i Sulh'], 'Tiryaki Sözleri, Cenap Şahabettin\'in kısa ve düşündürücü özdeyişlerini içerir; Türk edebiyatında aforizma türünün önemli örneklerindendir.'),
  ('Cenap Şahabettin\'in tıp eğitimini tamamlamak için gittiği ve şiir anlayışının biçimlendiği şehir hangisidir?', 'Paris', ['Londra', 'Berlin', 'Viyana'], 'Cenap Şahabettin Paris\'te deri hastalıkları üzerine uzmanlaştı; Fransız şiiriyle burada yakından tanıştı.'),
  ('Cenap Şahabettin\'in şiirlerinde sıkça görülen "renk ve ses ile duygu arasında bağ kurma" özelliği hangi kavramla açıklanır?', 'Duyular arası aktarma', ['Telmih', 'Tevriye ve kinaye', 'Tecahül-i arif ve istifham'], 'Cenap sembolistler gibi renk, ses ve kokuyu birbirine bağlayarak duyular arası aktarma (sinestezi) yoluyla zengin imgeler kurar.'),
  ('Mai ve Siyah\'ın sonunda Ahmet Cemil\'in yaşadıkları için hangisi doğrudur?', 'Hayallerinden vazgeçip annesiyle birlikte İstanbul\'dan ayrılır.', ['Yazdığı kitap büyük ilgi görür, zengin olur ve İstanbul\'da bir yalı satın alır.', 'Paris\'e gidip ünlü bir şair olur.', 'Kız kardeşiyle birlikte yeni bir gazete kurar.'], 'Kız kardeşi İkbal\'in ölümü gibi yıkımlar sonunda Ahmet Cemil, hayallerinden vazgeçip taşrada memurluğa giderken İstanbul\'dan ayrılır.'),
  ('Mai ve Siyah\'ta Servet-i Fünun ile eski edebiyat taraftarları arasındaki tartışmaların da yer alması romana hangi niteliği kazandırır?', 'Döneminin edebî ortamını yansıtan bir belge niteliği', ['Masalsı ve olağanüstü bir nitelik', 'Tarihî bir destan niteliği', 'Yalnızca bir aşk romanı ve aile hikâyesi olma niteliği'], 'Romanda Ahmet Cemil\'in çevresindeki edebiyat tartışmaları, Servet-i Fünun döneminin edebî havasını yansıtır.'),
  ('Aşk-ı Memnu romanında kişilerin kalıtım ve çevrenin etkisiyle davranmaları, özellikle Bihter\'in annesine benzeyeceği korkusu, romanda hangi akımın etkisini gösterir?', 'Natüralizm', ['Sembolizm', 'Romantizm', 'Klasisizm ve hümanizm'], 'Kalıtımın insan davranışını belirlediği düşüncesi natüralizmin temel ilkelerindendir; Bihter\'in annesi Firdevs Hanım\'a benzeme korkusu bu etkiyi yansıtır.'),
  ('Halit Ziya\'nın Kırık Hayatlar romanının başkişisi olan Ömer Behiç\'in mesleği nedir?', 'Doktor', ['Öğretmen', 'Avukat', 'Şair'], 'Kırık Hayatlar, doktor Ömer Behiç\'in iki ayrı hayat arasında bölünmüşlüğünü ve aile içindeki çöküşü anlatır.'),
  ('Halit Ziya Uşaklıgil\'in roman tekniği için aşağıdakilerden hangisi söylenemez?', 'Okura sık sık seslenip ahlak dersleri verir.', ['Ayrıntılı tasvirlere ve ruh çözümlemelerine yer verir.', 'Olayları nesnel bir anlatıcı bakışıyla aktarır.', 'Kişileri çevreleriyle birlikte gerçekçi biçimde işler.'], 'Halit Ziya, Tanzimat yazarlarının aksine araya girip okura öğüt vermez; tasvir ve ruh çözümlemesinde ustadır.'),
  ('Halit Ziya\'nın edebî hayatını ve dönemini anlattığı hatırat eseri hangisidir?', 'Kırk Yıl', ['Bir Acı Hikâye', 'Bir Yazın Tarihi', 'Solgun Demet'], 'Kırk Yıl, Halit Ziya\'nın çocukluğundan Servet-i Fünun yıllarına kadar olan hayatını ve edebî çevresini anlatır.'),
  ('Eylül romanında Suat ile Necip arasındaki yasak aşkı trajik biçimde sona erdiren olay hangisidir?', 'Evde çıkan yangın', ['Suat\'ın kocasından boşanıp Necip\'le evlenmesi', 'Necip\'in Avrupa\'ya kaçması', 'Süreyya\'nın Necip\'i düelloya çağırması'], 'Romanın sonunda çıkan yangında Suat ölür; yasak aşk böylece trajik biçimde son bulur.'),
  ('Mehmet Rauf\'un Eylül romanında olaylardan çok ruh hâllerinin ayrıntılı çözümlenmesi hangi sonucu doğurur?', 'Olay örgüsünün zayıf, iç dünyanın ise baskın olması', ['Romanın macera romanına dönüşmesi', 'Kişilerin iyi ve kötü olarak ayrılıp tek boyutlu tiplere dönüşmesi', 'Yazarın araya girip öğüt vermesi'], 'Eylül\'de dış olaylar çok azdır; romanın ağırlığını kişilerin duygu ve düşünceleri oluşturur. Bu, psikolojik romanın belirgin özelliğidir.'),
  ('Hüseyin Cahit Yalçın\'ın II. Meşrutiyet\'ten sonra Tevfik Fikret ile birlikte çıkardığı ve İttihat ve Terakki\'nin sözcüsü durumuna gelen gazete hangisidir?', 'Tanin', ['Sabah', 'İkdam', 'Tasvir-i Efkâr'], 'Tanin 1908\'de yayına başladı; Hüseyin Cahit bu gazetedeki siyasi yazılarıyla tanındı.'),
  ('Hüseyin Cahit Yalçın\'ın Servet-i Fünun içindeki rolü düşünüldüğünde onun en çok hangi yönüyle öne çıktığı söylenebilir?', 'Topluluğu eleştirilere karşı savunan tartışmacı yazar ve eleştirmen olmasıyla', ['Topluluğun en önemli şairi olmasıyla', 'Topluluğun tiyatro yazarı olmasıyla', 'Topluluğun dergisini kuran yayıncı olmasıyla'], 'Hüseyin Cahit, Ahmet Mithat\'ın Dekadanlar yazısı gibi saldırılara karşı Servet-i Fünun\'u savunan polemikçi ve eleştirmen kimliğiyle öne çıkar.'),
  ('Süleyman Nazif\'in İtilaf donanmasının İstanbul\'a girişine ve Fransız generalin şehre girişine tepki olarak yazdığı ünlü makale hangisidir?', 'Kara Bir Gün', ['Yeni Lisan', 'Edebiyat ve Hukuk', 'Dekadanlar'], 'Kara Bir Gün (1919), Fransız General Franchet d\'Esperey\'in İstanbul\'a girişini protesto eden yazısıdır.'),
  ('Süleyman Nazif\'in İngilizlerce sürgün edildiği yerde yaşadıklarını anlattığı eser hangisidir?', 'Malta Geceleri', ['Firak-ı Irak', 'Batarya ile Ateş', 'Gurbet Hikâyeleri'], 'Malta Geceleri, Süleyman Nazif\'in Malta\'ya sürgün edildiği dönemde yazdığı eserlerindendir.'),
  ('Ahmet Hikmet Müftüoğlu\'nun Türkçülük düşüncesini yansıtan ve millî konulara yönelen hikâyelerini topladığı eseri hangisidir?', 'Çağlayanlar', ['Haristan ve Gülistan', 'Solgun Demet', 'Hayat-ı Muhayyel'], 'Çağlayanlar, Ahmet Hikmet\'in millî duyarlılık taşıyan hikâyelerinden oluşur; Haristan ve Gülistan ise daha önceki dönemine aittir.'),
  ('Ahmet Hikmet Müftüoğlu\'nun Servet-i Fünun çevresinde başlayıp daha sonra Millî Edebiyat anlayışına geçmesi onun hakkında hangi yargıya varılmasını sağlar?', 'İki dönem arasında köprü olan bir yazar olduğu', ['Yalnız Tanzimat döneminde eser verdiği', 'Hiçbir edebî topluluğa yakın durmadığı', 'Yalnız Divan şiiri geleneğinde yazdığı'], 'Ahmet Hikmet, Servet-i Fünun üslubuyla başlayıp Türkçü bir çizgiye geçerek iki dönem arasında geçiş örneği olmuştur.'),
  ('Servet-i Fünun yazarları için aşağıdakilerden hangisi söylenemez?', 'Romanlarında Anadolu köylerini sıkça mekân olarak seçmişlerdir.', ['Eserlerinde bireysel duygulara ağırlık vermişlerdir.', 'Ağır ve süslü bir dil kullanmışlardır.', 'Batı edebiyatını, özellikle Fransız edebiyatını örnek almışlardır.'], 'Servet-i Fünun romanının mekânı büyük ölçüde İstanbul, yalı ve konak çevresidir; Anadolu\'ya yönelme Millî Edebiyat\'ta yaygınlaşır.'),
  ('Ahmet Rasim\'in İstanbul hayatını gözlemlere dayanarak anlattığı ve fıkra türünün başarılı örneklerini içeren eseri hangisidir?', 'Şehir Mektupları', ['Hayat ve Kitaplar', 'Bize Göre', 'Tiryaki Sözleri'], 'Şehir Mektupları, Ahmet Rasim\'in İstanbul\'un gündelik hayatını sohbet havasında ve mizahi bir dille aktardığı yazılarından oluşur.'),
  ('Ahmet Rasim\'in öğrenciliğini ve okul yıllarındaki disiplin anlayışını anlattığı anı eseri hangisidir?', 'Falaka', ['Ömer\'in Çocukluğu', 'Kırk Yıl', 'Defter-i Amal'], 'Falaka, Ahmet Rasim\'in Darüşşafaka\'daki öğrencilik yıllarını anlattığı hatırat niteliğindeki eseridir.'),
  ('Ahmet Rasim\'in edebiyatın dışında da tanındığı alan hangisidir?', 'Musiki ve şarkı bestekârlığı', ['Hattatlık ve tezhip', 'Mimarlık', 'Resim ve heykel'], 'Ahmet Rasim aynı zamanda Türk musikisinde şarkılar besteleyen bir bestekârdı.'),
  ('Servet-i Fünun topluluğunun dağılmasından sonra üyelerinin büyük bölümü için hangisi söylenebilir?', 'Edebiyatı bırakıp gazetecilik, siyaset ve devlet görevlerine yönelmişlerdir.', ['Topluca Fecr-i Âti\'ye katılıp onun yönetimini üstlenmişlerdir.', 'Planladıkları gibi Yeni Zelanda\'ya göç etmişlerdir.', 'Halk şiiri biçimlerine geçip koşmalar yazmışlardır.'], '1901\'den sonra topluluk dağıldı; Hüseyin Cahit siyasete, Halit Ziya saraya, diğerleri çeşitli görevlere yöneldi.'),
  ('Servet-i Fünun çevresindeki şairlerden Faik Ali Ozansoy\'un kardeşi olan ve siyasi makaleleriyle tanınan yazar kimdir?', 'Süleyman Nazif', ['Hüseyin Cahit Yalçın', 'Ali Ekrem Bolayır', 'Cenap Şahabettin'], 'Faik Ali Ozansoy ile Süleyman Nazif Diyarbakırlı iki kardeştir; Faik Ali\'nin Fani Teselliler adlı şiir kitabı vardır.'),
  ('Fecr-i Âti topluluğuna yöneltilen en yaygın eleştiri hangisidir?', 'Servet-i Fünun\'u büyük ölçüde tekrar edip yeni bir şey getirememesi', ['Hece ölçüsünü zorla kabul ettirmeye çalışması', 'Yalnız tarihî roman yazması', 'Halk şiirini aşırı taklit edip Divan geleneğini bütünüyle yok sayması'], 'Fecr-i Âti, Servet-i Fünun\'un dil ve sanat anlayışını sürdürdüğü için özgün bir çizgi kuramamakla eleştirilmiş, kısa sürede dağılmıştır.'),
  ('Fecr-i Âti\'de yer alıp sonradan Millî Edebiyat ve Cumhuriyet döneminde roman alanında öne çıkan yazarlar hangi seçenekte birlikte verilmiştir?', 'Yakup Kadri Karaosmanoğlu ve Refik Halit Karay', ['Halit Ziya Uşaklıgil ve Mehmet Rauf', 'Namık Kemal ve Ahmet Mithat', 'Recaizade Mahmut Ekrem ile Sami Paşazade Sezai'], 'Yakup Kadri ve Refik Halit, Fecr-i Âti\'den çıkıp Millî Edebiyat ve sonrasında önemli romancılar olmuştur.'),
  ('Fecr-i Âti topluluğu ile Servet-i Fünun arasındaki benzerlik için en doğru yargı hangisidir?', 'İkisi de Batı edebiyatını örnek alan, bireyci ve ağır dilli bir anlayış taşır.', ['İkisi de Divan şiirine dönüşü savunmuştur.', 'İkisi de hece ölçüsünü benimseyen, halka seslenen ve sade dil kullanan topluluklardır.', 'İkisi de yalnız tiyatro alanında eser vermiştir.'], 'Fecr-i Âti, Servet-i Fünun\'un devamı niteliğinde; bireysellik, Fransız edebiyatı etkisi ve ağır dil iki topluluğun ortak yönleridir.'),
  ('Fecr-i Âti\'nin dağılmasından sonra en kalıcı şiir başarısını gösteren ve topluluktan ayrılarak kendine özgü çizgisini kuran şair kimdir?', 'Ahmet Haşim', ['Emin Bülent Serdaroğlu', 'Tahsin Nahit', 'Şahabettin Süleyman'], 'Ahmet Haşim, sembolist şiir anlayışıyla Fecr-i Âti\'nin en tanınmış ve kalıcı şairi olmuştur.'),
  ('Ahmet Haşim\'in "Şiir Hakkında Bazı Mülahazalar" adlı yazısında savunduğu görüş hangisidir?', 'Şiirin anlaşılmak için değil, duyulmak için yazıldığı', ['Şiirde yalnız hece ölçüsünün kullanılabileceği', 'Şiirin her şeyden önce halkı eğitmek ve aydınlatmak için yazılması gerektiği', 'Şiirin olayları anlatan bir hikâye olduğu'], 'Piyale\'nin önsözü olan bu yazıda Haşim, şiir dilinin nesir dili gibi anlaşılmak için değil, musikiye yakın bir dil olarak duyulmak için yaratıldığını söyler.'),
  ('Ahmet Haşim\'in hangi şehirde doğduğu ve bu şehrin şiirindeki göl, su, akşam imgelerine kaynaklık ettiği düşünülür?', 'Bağdat', ['Şam', 'Selanik', 'Üsküp'], 'Haşim 1880\'lerde Bağdat\'ta doğmuş; çocukluğunda Dicle kıyısındaki izlenimlerin şiirindeki su ve akşam imgelerine yansıdığı kabul edilir.'),
  ('Ahmet Haşim\'in Bursa\'daki leylek hastanesinden yola çıkarak yazdığı ve adını bu hastaneden alan deneme kitabı hangisidir?', 'Gurabahane-i Laklakan', ['Bize Göre', 'Frankfurt Seyahatnamesi', 'Göl Saatleri'], 'Gurabahane-i Laklakan "leyleklerin hastanesi" anlamına gelir; Haşim\'in toplumu eleştiren düzyazılarından oluşur.'),
  ('Ahmet Haşim\'in Almanya\'ya tedavi için yaptığı yolculuğu anlattığı eseri hangisidir?', 'Frankfurt Seyahatnamesi', ['Avrupa Mektupları', 'Paris\'te Bir Türk', 'Avrupa\'da Bir Cevelan'], 'Frankfurt Seyahatnamesi (1933), Haşim\'in Almanya izlenimlerini ince bir mizahla anlattığı gezi yazılarıdır.'),
  ('Ahmet Haşim\'in şiir anlayışına göre bir şiirde aşağıdakilerden hangisi en az önemlidir?', 'Açık ve kesin bir anlam iletmek', ['Musiki ve ahenk oluşturmak', 'Duygu ve hayal uyandırmak', 'Çağrışım zenginliği sağlamak'], 'Haşim\'e göre şiirin görevi bir anlam aktarmak değil, okurda müzikal bir etki ve çağrışım uyandırmaktır.'),
  ('Yusuf Akçura\'nın 1911\'de çıkardığı ve Türkçülük düşüncesinin önemli yayın organı olan dergi hangisidir?', 'Türk Yurdu', ['Genç Kalemler', 'Dergâh', 'Sırat-ı Müstakim'], 'Türk Yurdu, Türk Ocakları\'nın da yayın organı olmuş, Türkçülük akımının başlıca dergilerinden biri olmuştur.'),
  ('Ziya Gökalp\'in 1917\'de çıkardığı ve Millî Edebiyat yazarlarının önemli bir bölümünü bir araya getiren dergi hangisidir?', 'Yeni Mecmua', ['Türk Yurdu', 'Hürriyet', 'Servet-i Fünun'], 'Yeni Mecmua, Ziya Gökalp\'in yönetiminde Millî Edebiyat\'ın ve Türkçülüğün etkin bir yayın organı olmuştur.'),
  ('Mehmet Akif Ersoy\'un şiirlerinin büyük bölümünü yayımladığı ve İslamcı düşüncenin sözcüsü olan dergi hangisidir?', 'Sırat-ı Müstakim', ['Genç Kalemler', 'Türk Yurdu', 'Dergâh'], 'Sırat-ı Müstakim, daha sonra Sebilürreşad adını almış; Akif\'in şiirleri ve yazıları bu dergide yayımlanmıştır.'),
  ('Yahya Kemal\'in çevresindeki genç yazarların 1921\'de çıkardığı ve Bergson felsefesinin etkisinin görüldüğü dergi hangisidir?', 'Dergâh', ['Yeni Mecmua', 'Genç Kalemler', 'Servet-i Fünun'], 'Dergâh, Mütareke yıllarında Yahya Kemal\'in yol göstericiliğinde çıkarılmış; Ahmet Hamdi Tanpınar, Nurullah Ataç gibi gençler de burada yazmıştır.'),
  ('Mütareke yıllarında İstanbul\'da yayımlanan mizah dergisi Aydede\'yi çıkaran yazar kimdir?', 'Refik Halit Karay', ['Ahmet Rasim', 'Ömer Seyfettin', 'Yusuf Ziya Ortaç'], 'Aydede (1922), Refik Halit\'in çıkardığı mizah dergisidir; Yusuf Ziya Ortaç ise Akbaba\'yı çıkarmıştır.'),
  ('Yeni Lisan makalesinde savunulan ilkeler arasında aşağıdakilerden hangisi yer almaz?', 'Arapça ve Farsça çoğul eklerinin korunması', ['Türkçeye yerleşmiş yabancı kelimelerin kullanılması', 'Arapça ve Farsça tamlamaların kullanılmaması', 'İstanbul Türkçesinin yazı dili olarak esas alınması'], 'Yeni Lisan, Arapça ve Farsça dil bilgisi kurallarının, çoğul eklerinin ve tamlamaların bırakılmasını ister; yerleşmiş kelimeler ise kabul edilir.'),
  ('Yeni Lisan anlayışına göre "Evrak-ı perişan" yerine hangi kullanım önerilir?', 'Perişan kâğıtlar', ['Evrak-ı perişaniye', 'Perişaniyat-ı evrak', 'Evrâkü\'l-perişan'], 'Yeni Lisan, Farsça tamlama kuralı yerine Türkçe sıfat tamlamasının kullanılmasını savunur; "perişan kâğıtlar" bu anlayışa uygundur.'),
  ('Millî Edebiyat ile Servet-i Fünun karşılaştırıldığında aşağıdaki eşleştirmelerden hangisi yanlıştır?', 'Millî Edebiyat: aruz ve ağır dil; Servet-i Fünun: hece ve sade dil', ['Millî Edebiyat: Anadolu; Servet-i Fünun: İstanbul', 'Millî Edebiyat: toplum ve millet; Servet-i Fünun: birey', 'Millî Edebiyat: halka seslenme; Servet-i Fünun: seçkinlere seslenme'], 'Bu eşleştirme ters çevrilmiştir: Millî Edebiyat hece ve sade dili, Servet-i Fünun aruz ve ağır dili benimsemiştir.'),
  ('Ömer Seyfettin\'in Balkan Savaşı sırasında Bulgar subayı Radko Draganof\'un zulmünü anlattığı hikâyesi hangisidir?', 'Beyaz Lale', ['Primo Türk Çocuğu', 'Diyet', 'And'], 'Beyaz Lale, Balkan Savaşı\'nda Türk halkına yapılan zulmü anlatan, Ömer Seyfettin\'in en sert hikâyelerinden biridir.'),
  ('Ömer Seyfettin\'in hikâyelerinin konularına göre gruplandırılmasında "tarihî hikâyeler" grubuna giren eser hangisidir?', 'Forsa', ['Kaşağı', 'Bomba', 'Bahar ve Kelebekler'], 'Forsa, Osmanlı denizcilik tarihinden alınmış bir olayı işler; Kaşağı çocukluk anısı, Bomba ise Makedonya\'daki komitacılık olaylarına dayanır.'),
  ('Ömer Seyfettin\'in "Efruz Bey" adlı uzun hikâyesinde alaya aldığı tip hangisidir?', 'Her akıma uyup çıkarına göre görüş değiştiren fırsatçı tip', ['Vatanı için canını veren kahraman asker', 'Köyünü terk etmeyen çalışkan köylü', 'Kitaplara gömülmüş bilge bir derviş'], 'Efruz Bey, dönemin moda akımlarına göre kılık değiştiren, gerçekte hiçbir şeye inanmayan bir fırsatçıdır.'),
  ('Ömer Seyfettin\'in hikâyelerinde gözlemlediği Balkan olaylarının kaynağında onun hangi deneyimi yer alır?', 'Subay olarak Rumeli\'de görev yapması ve Balkan Savaşı\'nda esir düşmesi', ['Avrupa\'da uzun yıllar diplomat olarak bulunup Balkan devletlerini incelemesi', 'Gazeteci olarak Paris\'te yaşaması', 'Bağdat\'ta öğretmenlik yapması'], 'Ömer Seyfettin, Rumeli\'de subay olarak görev yapmış ve Balkan Savaşı sırasında Yunanlılara esir düşmüştür; bu deneyimler hikâyelerine yansımıştır.'),
  ('Ömer Seyfettin\'in doğduğu ilçe hangisidir?', 'Gönen', ['Bolayır', 'Ayvalık', 'Akhisar'], 'Ömer Seyfettin 1884\'te Balıkesir\'in Gönen ilçesinde doğmuştur.'),
  ('Ömer Seyfettin\'in hikâyecilikte örnek aldığı, olay hikâyesinin Batı\'daki en önemli temsilcisi sayılan yazar kimdir?', 'Guy de Maupassant', ['Anton Çehov', 'Edgar Allan Poe', 'Émile Zola'], 'Olayın merak uyandıracak biçimde kurulup çarpıcı bir sonla bittiği hikâye tipi Maupassant\'a dayanır; Çehov ise durum hikâyesinin temsilcisidir.'),
  ('Ziya Gökalp\'in "Türkleşmek, İslamlaşmak, Muasırlaşmak" adlı eserinde savunduğu düşünce nasıl özetlenebilir?', 'Millî kültür, İslam ahlakı ve çağdaş medeniyetin uzlaştırılması', ['Dinin toplum hayatından bütünüyle çıkarılması', 'Batı medeniyetinin tümüyle reddedilip Orta Asya geleneklerine dönülmesi', 'Osmanlıcılığın tek çıkış yolu olarak benimsenmesi'], 'Gökalp, Türk milletinin kendi kültürüne bağlı, Müslüman ve Batı\'nın bilim ve tekniğine açık bir toplum olmasını savunur.'),
  ('Ziya Gökalp\'in kültür ile medeniyet arasında yaptığı ayrıma göre "hars" kavramı neyi ifade eder?', 'Bir millete özgü değerler bütünü olan kültürü', ['Milletler arasında ortak olan teknik ve bilimsel birikimi', 'Bir devletin askerî gücünü', 'Sanayi ve ticaret düzenini'], 'Gökalp\'e göre hars (kültür) millîdir; medeniyet ise milletlerarası ve ortaktır.'),
  ('Ziya Gökalp\'in Türk masallarını ve destanlarını şiir ve düzyazı biçiminde yeniden yazdığı eseri hangisidir?', 'Altın Işık', ['Türkçülüğün Esasları', 'Yeni Hayat', 'Türk Töresi'], 'Altın Işık (1923), halk masalları ve destanlardan derlenmiş, sade Türkçeyle yeniden yazılmış metinlerden oluşur.'),
  ('Ziya Gökalp\'in şiirleri için aşağıdakilerden hangisi en doğru değerlendirmedir?', 'Fikirlerini yaymak amacıyla yazılmış, sanat değerinden çok öğretici yönü ağır basan şiirlerdir.', ['Saf şiir anlayışıyla yazılmış, anlamdan çok musikiye önem veren sembolist şiirlerdir.', 'Bütünüyle aruzla yazılmış Divan tarzı gazellerdir.', 'Yalnız aşk konulu bireysel şiirlerdir.'], 'Gökalp şiiri bir düşünce aracı olarak kullanmış; Kızıl Elma ve Yeni Hayat\'taki şiirleri Türkçülük ülküsünü yaymayı amaçlar.'),
  ('Ziya Gökalp\'in doğduğu ve gençlik yıllarında Küçük Mecmua\'yı da çıkardığı şehir hangisidir?', 'Diyarbakır', ['Selanik', 'Erzurum', 'Konya'], 'Diyarbakır\'da doğan Gökalp, Malta sürgününden sonra döndüğü Diyarbakır\'da Küçük Mecmua\'yı çıkarmıştır.'),
  ('Safahat\'ın ikinci kitabı olan Süleymaniye Kürsüsünde\'de vaaz veren kişi kimdir?', 'Abdürreşit İbrahim', ['Köse İmam', 'Seyfi Baba', 'Hocazade'], 'Bu kitapta Sibiryalı gezgin ve din adamı Abdürreşit İbrahim, Süleymaniye Camii\'nin kürsüsünden İslam dünyasının durumunu anlatır.'),
  ('Mehmet Akif\'in şiirlerinde manzum hikâye türünü başarıyla kullanması ona ne kazandırmıştır?', 'Toplumun gerçek hayatını canlı tiplerle ve konuşma diliyle yansıtma imkânı', ['Şiirlerini yalnız Arapça ve Farsça bilen seçkinlerin anlamasını sağlama', 'Aruzu tamamen bırakma fırsatı', 'Sembolist bir şiir kurma imkânı'], 'Seyfi Baba, Küfe, Mahalle Kahvesi gibi manzum hikâyelerde Akif, halkın gündelik hayatını gerçekçi bir gözle anlatır.'),
  ('Mehmet Akif\'in Safahat\'ının son kitabı olan ve Mısır\'da yaşarken yazdığı şiirleri içeren eser hangisidir?', 'Gölgeler', ['Asım', 'Hatıralar', 'Fatih Kürsüsünde'], 'Gölgeler (1933), Akif\'in Mısır yıllarında yazdığı, daha içe dönük ve hüzünlü şiirlerini içerir.'),
  ('Mehmet Akif, İstiklal Marşı yarışması için konan ödüle ilişkin nasıl bir tutum göstermiştir?', 'Ödülü almayı istememiş, ödül bir hayır kurumuna bağışlanmıştır.', ['Ödül miktarının artırılmasını istemiştir.', 'Ödülü alıp Mısır\'a gitmek ve orada yaşamak için kullanmıştır.', 'Ödülü Safahat\'ı bastırmak için harcamıştır.'], 'Para ödülü nedeniyle yarışmaya katılmak istemeyen Akif, Hamdullah Suphi\'nin ısrarıyla şiirini vermiş; ödül Darülmesai adlı kuruma bağışlanmıştır.'),
  ('Mehmet Akif\'in İstiklal Marşı\'nı Safahat\'a almamasının nedeni olarak kendisinin belirttiği düşünce hangisidir?', 'Marşı milletine armağan ettiğini, kendi eseri saymadığını', ['Marşın yasaklanacağından korktuğunu', 'Marşın edebî değerini düşük bulduğunu ve yeniden yazmak istediğini', 'Marşı başka bir şaire ait saydığını'], 'Akif, İstiklal Marşı\'nın milletin malı olduğunu düşündüğünden onu kendi şiir kitaplarına almamıştır.'),
  ('Mehmet Akif TBMM\'de hangi ilin milletvekili olarak bulunuyordu?', 'Burdur', ['Konya', 'Ankara', 'Kastamonu'], 'Akif Birinci Meclis\'te Burdur milletvekiliydi; İstiklal Marşı\'nı Ankara\'daki Taceddin Dergâhı\'nda yazdığı bilinir.'),
  ('Yahya Kemal\'in sağlığında kitap yayımlamaması nedeniyle ilk şiir kitabı olan Kendi Gök Kubbemiz ne zaman yayımlanmıştır?', 'Ölümünden sonra, 1961\'de', ['1912\'de Paris dönüşünde', '1921\'de Dergâh yıllarında', '1938\'de Atatürk\'ün ölümünden önce'], 'Yahya Kemal şiirlerini kitaplaştırmadı; Kendi Gök Kubbemiz, ölümünden sonra 1961\'de yayımlandı.'),
  ('Yahya Kemal\'in Divan şiiri estetiğine bağlı kalarak yazdığı şiirleri topladığı eser hangisidir?', 'Eski Şiirin Rüzgârıyla', ['Kendi Gök Kubbemiz', 'Aziz İstanbul', 'Eğil Dağlar'], 'Eski Şiirin Rüzgârıyla, Yahya Kemal\'in Divan şiirinin dil ve üslubunu yeniden yorumladığı gazel ve şarkılarını içerir.'),
  ('Yahya Kemal\'in tarih anlayışında öne çıkan "Türk tarihinin başlangıcı" görüşü hangisidir?', 'Türk milletinin vatan tarihinin 1071 Malazgirt ile başladığı', ['Türk tarihinin Cumhuriyet\'in ilanıyla başladığı', 'Türk tarihinin İstanbul\'un fethiyle başladığı', 'Türk tarihinin yalnız Orta Asya bozkırlarında geçtiği ve Anadolu\'nun sonradan önem kazandığı'], 'Yahya Kemal, Anadolu\'nun Türk vatanı oluşunu 1071\'den başlatır; bu, onun "coğrafya ve tarih" anlayışının temelidir.'),
  ('Yahya Kemal\'in Paris\'te bulunduğu yıllarda tanıştığı ve şiir anlayışını etkileyen akımlar arasında özellikle hangisi öne çıkar?', 'Parnasizm', ['Fütürizm', 'Dadaizm', 'Sürrealizm'], 'Yahya Kemal Paris\'te parnasizmden ve sembolizmden etkilenmiştir; biçim kusursuzluğu bu etkinin göstergesidir.'),
  ('Yahya Kemal\'in "Süleymaniye\'de Bayram Sabahı" şiirinde dile getirdiği temel düşünce hangisidir?', 'Mimari, musiki ve toplumun bir bütün olarak millî kimliği yansıttığı', ['Dinin toplum hayatında hiçbir yeri olmadığı', 'İstanbul\'un artık eski güzelliğini tamamen yitirdiği', 'Bayramın yalnız çocuklar için anlamlı olduğu ve büyüklerin bu sevinci yitirdiği'], 'Şair Süleymaniye\'deki bayram namazında cemaati, camiyi ve Itri\'nin tekbirini bir arada görerek millî kimliğin sürekliliğini vurgular.'),
  ('Yahya Kemal\'in şiirinde Türk musikisinin ünlü bestecisini konu edinen ve onun eserlerinde milletin ruhunu bulan şiiri hangisidir?', 'Itri', ['Ses', 'Rindlerin Ölümü', 'Vuslat'], 'Itri şiirinde Yahya Kemal, bestecinin tekbirinde ve eserlerinde Türk milletinin ruhunu duyduğunu söyler.'),
  ('Yahya Kemal\'in Cumhuriyet döneminde yaptığı görevler arasında yer almayan hangisidir?', 'Sadrazamlık', ['Milletvekilliği', 'Varşova elçiliği', 'Pakistan büyükelçiliği'], 'Yahya Kemal milletvekilliği ve Varşova, Madrit, Lizbon, Karaçi\'de elçilik görevleri yapmıştır; sadrazamlık ise Osmanlı\'ya ait bir makamdır.'),
  ('Halide Edip\'in Sinekli Bakkal romanının kahramanı Rabia\'nın babası Tevfik\'in mesleği nedir?', 'Ortaoyunu oyuncusu', ['Mahalle imamı', 'Saray hekimi', 'Gemi kaptanı'], 'Tevfik, geleneksel ortaoyununda kadın rollerine çıkan bir oyuncudur; bu yüzden "Kız Tevfik" diye anılır.'),
  ('Halide Edip\'in II. Meşrutiyet sonrasında Türkçülük ülküsünü işlediği ve Kaya Alp ile Oğuz adlı kişilerin yer aldığı romanı hangisidir?', 'Yeni Turan', ['Handan', 'Seviye Talip', 'Raik\'in Annesi'], 'Yeni Turan (1912), Turancılık ve Türkçülük düşüncesini bir ütopya biçiminde anlatır.'),
  ('Halide Edip\'in 1919\'da işgallere karşı düzenlenen hangi mitingde yaptığı konuşmayla tanınır?', 'Sultanahmet Mitingi', ['Fatih Mitingi', 'Kadıköy Mitingi', 'Üsküdar Mitingi'], 'Halide Edip\'in Sultanahmet Mitingi\'nde yaptığı ateşli konuşma, Millî Mücadele\'ye halk desteğinin simgelerinden biri olmuştur.'),
  ('Halide Edip\'in ilk dönem romanlarından Handan\'ın öne çıkan özelliği nedir?', 'Eğitimli bir kadının iç dünyasını ve duygusal çatışmalarını işlemesi', ['Anadolu köylüsünün savaş yıllarındaki hayatını anlatması', 'Osmanlı\'nın kuruluş dönemini konu alması', 'Mizahi bir dille İstanbul\'un mahalle hayatını ve kahvehane sohbetlerini anlatması'], 'Handan, aydın bir kadının aşk ve evlilik çevresindeki ruhsal çatışmalarını psikolojik bir yaklaşımla işler.'),
  ('Halide Edip\'in romanlarında kadın kahramanların genel özelliği hangisidir?', 'Güçlü, eğitimli ve idealist kadınlar olmaları', ['Yalnız cariye ve köle kadınlar olmaları', 'Tamamen edilgen ve kaderine boyun eğen kadınlar olmaları', 'Hep saray çevresinden gelen, siyasetle ve toplumla ilgilenmeyen kadınlar olmaları'], 'Aliye, Ayşe, Rabia gibi kahramanlar güçlü kişilikli, toplum için sorumluluk taşıyan kadınlardır.'),
  ('Çalıkuşu romanında Feride\'nin öğretmenlik yaptığı ve romanda geniş yer tutan Anadolu köyünün adı nedir?', 'Zeyniler', ['Sarıova', 'Kuyucak', 'Sapanca'], 'Feride, Zeyniler köyünde zor şartlar altında öğretmenlik yapar; Sarıova ise Yeşil Gece\'deki kasabadır.'),
  ('Çalıkuşu romanının Millî Edebiyat döneminin özelliklerini taşıdığını gösteren yönü hangisidir?', 'Anadolu\'yu bir İstanbullu genç kızın gözüyle tanıtması', ['Olayların bütünüyle Boğaziçi yalılarında ve İstanbul konaklarında geçmesi', 'Ağır Arapça ve Farsça tamlamalarla yazılması', 'Divan şiirinin mazmunlarını romana taşıması'], 'Çalıkuşu, Feride\'nin Anadolu kasaba ve köylerinde yaşadıkları aracılığıyla Anadolu gerçeğini sade bir dille okura ulaştırır.'),
  ('Reşat Nuri\'nin Acımak romanında öğretmen Zehra\'nın babasına bakışını değiştiren olay nedir?', 'Babasının hatıra defterini okuması', ['Babasıyla birlikte hacca gitmesi', 'Babasının ona miras bırakması', 'Babasının ölmeden önce kendisinden özür dilemesi'], 'Zehra, ölüm döşeğindeki babasının defterini okuyunca onun da acılar çektiğini anlar ve "acımak" duygusunu öğrenir.'),
  ('Reşat Nuri Güntekin\'in Anadolu\'daki gezilerinde edindiği gözlemleri anlattığı eser hangisidir?', 'Anadolu Notları', ['Memleket Hikâyeleri', 'Anadolu\'da Bir Cevelan', 'Gurbet Hikâyeleri'], 'Anadolu Notları, Reşat Nuri\'nin müfettişlik sırasında dolaştığı Anadolu kasabalarına dair gözlem yazılarıdır.'),
  ('Yakup Kadri Karaosmanoğlu\'nun Kiralık Konak romanında kuşaklar arası çatışmayı temsil eden üç kuşak hangi seçenekte doğru verilmiştir?', 'Naim Efendi, Servet Bey, Seniha', ['Adnan Bey, Bihter, Nihal', 'Ali Rıza Bey, Şevket, Leyla', 'Felatun Bey, Rakım Efendi, Canan'], 'Kiralık Konak\'ta dede Naim Efendi, oğlu Servet Bey ve torun Seniha, değerlerin kuşaktan kuşağa değişimini temsil eder.'),
  ('Kiralık Konak\'ta Seniha\'ya âşık olan, şair ruhlu ve sonunda cepheye giden genç kimdir?', 'Hakkı Celis', ['Ahmet Celal', 'Behlül', 'Necip'], 'Hakkı Celis, Seniha\'nın yozlaşmış dünyasından uzaklaşıp savaşa katılır; onun bu tercihi millî değerlere dönüşü simgeler.'),
  ('Yakup Kadri\'nin II. Meşrutiyet dönemindeki siyasi parti çekişmelerini ve 31 Mart Olayı\'na giden süreci anlattığı romanı hangisidir?', 'Hüküm Gecesi', ['Sodom ve Gomore', 'Ankara', 'Panorama'], 'Hüküm Gecesi (1927), Meşrutiyet yıllarının siyasi çalkantılarını Ahmet Kerim adlı bir gazeteci üzerinden anlatır.'),
  ('Yaban romanının adının taşıdığı anlam, roman bütünü içinde nasıl yorumlanır?', 'Köylünün aydını kendinden saymayıp yabancı görmesi', ['Romanın baştan sona vahşi doğada ve dağlarda geçmesi', 'Kahramanın yabancı bir ülkeden gelmesi', 'Köylülerin şehre göç etmesi'], 'Ahmet Celal köylüleri anlamaya çalışsa da onlar için bir yabancıdır; roman aydın-halk kopukluğunu bu başlıkla özetler.'),
  ('Yakup Kadri\'nin 1932\'de arkadaşlarıyla birlikte çıkardığı ve devletçi bir kalkınma anlayışını savunan dergi hangisidir?', 'Kadro', ['Dergâh', 'Yeni Mecmua', 'Varlık'], 'Kadro dergisi, Şevket Süreyya Aydemir, Vedat Nedim Tör gibi isimlerle birlikte çıkarılmıştır.'),
  ('Yakup Kadri\'nin büyükelçilik yıllarındaki anılarını anlattığı eser hangisidir?', 'Zoraki Diplomat', ['Politikada 45 Yıl', 'Vatan Yolunda', 'Gençlik ve Edebiyat Hatıraları'], 'Zoraki Diplomat, Yakup Kadri\'nin Arnavutluk, Prag, Lahey, Bern gibi yerlerdeki elçilik görevlerini anlatır.'),
  ('Reşat Nuri Güntekin\'in Dudaktan Kalbe romanının kahramanı Kenan\'ın mesleği nedir?', 'Besteci ve müzisyen', ['Doktor ve üniversite hocası', 'Öğretmen', 'Asker'], 'Dudaktan Kalbe\'de müzisyen Kenan\'ın sanat ve aşk arasındaki çalkantılı hayatı anlatılır.'),
  ('Refik Halit\'in "yüzellilikler" listesine alınarak yurt dışında yaşadığı yıllarda yazdığı ve Suriye, Lübnan çevresini anlatan hikâye kitabı hangisidir?', 'Gurbet Hikâyeleri', ['Memleket Hikâyeleri', 'Bir Serencam', 'Rahmet'], 'Gurbet Hikâyeleri (1940), Refik Halit\'in Halep ve Beyrut\'ta geçirdiği sürgün yıllarının ürünüdür.'),
  ('Refik Halit Karay\'ın hikâyeciliği için en uygun değerlendirme hangisidir?', 'Anadolu\'yu romantik bir idealizm yerine gerçekçi bir gözle anlatmıştır.', ['Yalnız İstanbul yalılarını ve sosyeteyi anlatmıştır.', 'Hikâyelerini ağır bir Osmanlıcayla ve süslü üslupla yazmıştır.', 'Yalnız tarihî kahramanlık hikâyeleri yazmıştır.'], 'Refik Halit, Anadolu\'yu yüceltmek yerine yoksulluğu, cehaleti ve insan zaaflarını gerçekçi ve yer yer ironik bir dille vermiştir.'),
  ('Refik Halit Karay\'ın Urfa yöresinde geçen ve bir çete reisinin işgale karşı mücadelesini anlatan romanı hangisidir?', 'Çete', ['Yezid\'in Kızı', 'Sürgün', 'Nilgün'], 'Çete (1939), Millî Mücadele yıllarında Urfa çevresinde geçen bir romandır.'),
  ('Beş Hececiler\'in Türk şiirindeki rolü için en doğru değerlendirme hangisidir?', 'Hece ölçüsünü yaygınlaştırıp halk şiirinin ötesinde bir sanat ölçüsüne dönüştürmeye çalışmaları', ['Aruzu Türk şiirinde yeniden canlandırmaları', 'Serbest nazmın Türkiye\'deki ilk örneklerini vermeleri', 'Sembolizmi Türk şiirine getirmeleri'], 'Beş Hececiler, Millî Edebiyat\'ın hece ölçüsünü yaygınlaştırdı; bu ölçünün seçkin şiire de uygun olduğunu göstermeye çalıştılar.'),
  ('Yusuf Ziya Ortaç\'ın 1922\'de çıkardığı ve uzun yıllar yayımlanan mizah dergisi hangisidir?', 'Akbaba', ['Aydede', 'Diyojen', 'Kalem'], 'Akbaba, Yusuf Ziya Ortaç\'ın kurduğu ve Türk mizah basınının en uzun soluklu dergilerinden biri olan yayındır.'),
  ('Müfide Ferit Tek\'in Turancılık düşüncesini işlediği ve kahramanının adını taşıyan romanı hangisidir?', 'Aydemir', ['Yeni Turan', 'Handan', 'Dikmen Yıldızı'], 'Aydemir (1918), Müfide Ferit Tek\'in Türkçülük ve Turancılık ülküsünü işleyen romanıdır; Yeni Turan ise Halide Edip\'indir.'),
  ('Ruşen Eşref Ünaydın\'ın Çanakkale Savaşı sırasında Mustafa Kemal ile yaptığı söyleşi hangi türün önemli örneklerindendir?', 'Röportaj', ['Gezi yazısı', 'Fabl', 'Mensur şiir'], 'Ruşen Eşref\'in "Anafartalar Kumandanı Mustafa Kemal ile Mülakat" adlı yazısı, Türk edebiyatında röportaj türünün öncü örneklerindendir.'),
  ('Ruşen Eşref Ünaydın\'ın dönemin yazar ve şairleriyle yaptığı söyleşileri topladığı eser hangisidir?', 'Diyorlar ki', ['Bize Göre', 'Kırk Yıl', 'Hayat ve Kitaplar'], 'Diyorlar ki (1918), Abdülhak Hamit, Halit Ziya, Yahya Kemal gibi isimlerle yapılmış edebî söyleşileri içerir.'),
  ('Millî Mücadele yıllarında Anadolu\'ya geçip Mustafa Kemal\'in yanında yer alan ve bu dönemi anılarında anlatan yazar aşağıdakilerden hangisidir?', 'Halide Edip Adıvar', ['Halit Ziya Uşaklıgil', 'Hüseyin Rahmi Gürpınar', 'Cenap Şahabettin'], 'Halide Edip Anadolu\'ya geçerek Millî Mücadele\'ye katılmış; Türk\'ün Ateşle İmtihanı\'nda bu yılları anlatmıştır.'),
  ('Mütareke yıllarında İstanbul\'da yayımlanan ve işgale karşı Anadolu hareketini destekleyen yazılarıyla bilinen yazarlar arasında Kara Bir Gün makalesiyle tanınan isim kimdir?', 'Süleyman Nazif', ['Refik Halit Karay', 'Ali Kemal', 'Rıza Tevfik Bölükbaşı'], 'Süleyman Nazif\'in Kara Bir Gün makalesi, işgale karşı tepkinin simgesi olmuştur; Ali Kemal ise Anadolu hareketine karşı yazılarıyla bilinir.'),
  ('Enis Behiç Koryürek\'in şiirlerinde öne çıkan tema hangisidir?', 'Denizcilik, akıncılık ve tarih coşkusu', ['Bireysel aşk ve kıskançlık', 'Köy hayatının ekonomik sorunları', 'Tasavvufi vahdet ve fena'], 'Enis Behiç, Beş Hececiler arasında tarih, akıncılık ve deniz temalarıyla ayrılır; Miras ve Güneşin Ölümü başlıca kitaplarıdır.'),
  ('Halide Edip\'in Sinekli Bakkal romanında olayların geçtiği dönem ve mekân hangi seçenekte doğru verilmiştir?', 'II. Abdülhamit dönemi, İstanbul\'da bir mahalle', ['Kurtuluş Savaşı yılları, Ankara\'da bir köy', 'Lale Devri, Edirne\'de bir saray', 'Cumhuriyet\'in ilk yılları, İzmir\'de bir çiftlik'], 'Sinekli Bakkal, II. Abdülhamit döneminde İstanbul\'daki Sinekli Bakkal mahallesinde geçen bir töre romanıdır.'),
  ('Şemsettin Sami\'nin Gave adlı oyununun konusunu aldığı kaynak hangisidir?', 'İran mitolojisinde zalim Dahhak\'a karşı ayaklanan demirci Kave efsanesi', ['Kırım hanlarının tarihi', 'Endülüs\'ün fethi', 'Arnavut dağlılarının söz tutma geleneği ve bu uğurda yapılan fedakârlıklar'], 'Gave, Şehname\'de de anlatılan demirci Kave\'nin zalim hükümdara başkaldırısını işler; Besa ise Arnavut geleneğine dayanır.'),
  ('"Diyâr-ı küfrü gezdim beldeler kâşâneler gördüm / Dolaştım mülk-i İslâm\'ı bütün vîrâneler gördüm" beytinin şairi kimdir?', 'Ziya Paşa', ['Namık Kemal', 'Şinasi', 'Recaizade Mahmut Ekrem'], 'Bu beyit, Ziya Paşa\'nın Avrupa ile İslam dünyası arasındaki gelişmişlik farkını acı bir dille anlattığı ünlü gazelinden alınmıştır.'),
  ('"Diyâr-ı küfrü gezdim beldeler kâşâneler gördüm / Dolaştım mülk-i İslâm\'ı bütün vîrâneler gördüm" beytinde öne çıkan duygu ve düşünce hangisidir?', 'Batı\'nın bayındırlığı karşısında İslam dünyasının geri kalmışlığına duyulan acı', ['Ölüm karşısındaki teslimiyet', 'Sevgiliye duyulan özlem ve ayrılığın verdiği acı', 'Doğanın ve büyük şehirlerin güzelliğine duyulan hayranlık ve coşku'], 'Şair Avrupa şehirlerinin gelişmişliğini İslam ülkelerinin yıkıklığıyla karşılaştırarak geri kalmışlığa duyduğu üzüntüyü dile getirir.'),
  ('"Ne mümkün zulm ile bîdâd ile imhâ-yı hürriyet / Çalış idrâkini kaldır muzaffer ol cehâletten" beytinde şair hürriyeti korumanın yolunu neye bağlar?', 'Bilgi ve aydınlanmaya', ['Silahlı mücadeleye', 'Padişaha bağlılığa', 'Dünyadan el çekip inzivaya çekilmeye'], 'Namık Kemal\'in Hürriyet Kasidesi\'nden alınan beyitte hürriyetin cehaletten kurtulmakla, idrakin yükselmesiyle korunacağı söylenir.'),
  ('Şinasi\'nin Paris\'te bulunduğu yıllarda tanıştığı ve kendisini etkileyen Fransız şair ve devlet adamı kimdir?', 'Lamartine', ['Victor Hugo', 'Baudelaire', 'Voltaire'], 'Şinasi Paris\'teki öğrenimi sırasında Lamartine ve Ernest Renan gibi isimlerle tanışmıştır; Tercüme-i Manzume\'de Lamartine\'den de çeviriler vardır.'),
  ('Abdülhak Hamit\'in Sahra adlı eserindeki şiirlerin yapısı için hangisi doğrudur?', 'Şehir ile köy hayatı arasındaki karşıtlığı işleyen pastoral şiirlerden oluşur.', ['Kahramanlık destanlarından oluşan, akıncıları ve gazileri anlatan uzun bir manzumedir.', 'Tasavvufi gazellerden oluşan bir divandır.', 'Mektup biçiminde yazılmış bir romandır.'], 'Sahra\'da şair, şehrin yapaylığını kırın sadeliğiyle karşılaştırır; bu, Türk şiirinde yeni bir duyarlılıktır.'),
  ('Abdülhak Hamit Tarhan\'ın şiirlerinde sıkça işlediği temalar arasında aşağıdakilerden hangisi yer almaz?', 'Köylünün toprak ve öküz sorunu', ['Ölüm ve ölümden sonrası', 'Allah ve evren üzerine sorgulamalar', 'Aşk ve kadın'], 'Hamit metafizik konulara, ölüme ve aşka yönelmiştir; köylünün ekonomik sorunu ise Nabizade\'nin Karabibik\'inde işlenir.'),
  ('Tanzimat dönemi tiyatrosunda "töre komedisi" olarak nitelendirilen bir eserin özelliği hangisidir?', 'Toplumun gelenek ve göreneklerindeki aksaklıkları güldürerek eleştirmesi', ['Mitolojik tanrıları konu alması', 'Tarihî kahramanların hayatını trajik biçimde ve manzum olarak anlatması', 'Yalnız müzikli ve danslı bölümlerden oluşması'], 'Şair Evlenmesi gibi töre komedileri, evlenme gelenekleri gibi toplumsal âdetlerdeki aksaklıkları gülmece yoluyla eleştirir.'),
  ('Tanzimat döneminde Batılı tiyatronun yaygınlaşmasıyla geleneksel Türk tiyatrosu (Karagöz, ortaoyunu) için ne söylenebilir?', 'Batı tarzı tiyatro karşısında zamanla gerilemiştir.', ['Batı tiyatrosunu tamamen ortadan kaldırıp tek tiyatro türü olarak kalmıştır.', 'Yalnız sarayda oynanır hâle gelip güçlenmiştir.', 'Batı tiyatrosuyla birleşerek operaya dönüşmüştür.'], 'Batı tarzı sahne tiyatrosunun yayılmasıyla Karagöz ve ortaoyunu eski önemini yitirmeye başlamıştır.'),
  ('Bir okuyucu "kafiye kulak içindir" görüşünü savunan şairin eserlerini okumak isterse aşağıdakilerden hangisini seçmelidir?', 'Ateşpâre', ['Zemzeme', 'Takdir-i Elhan', 'Pejmürde'], '"Kafiye kulak içindir" görüşü Muallim Naci\'ye aittir; Ateşpâre onun eseridir. Diğerleri "kafiye göz içindir" diyen Recaizade\'nin eserleridir.'),
  ('Tanzimat döneminde Batı\'dan alınan yeni türlerin ilk örnekleri ile yazarları eşleştirildiğinde hangisi yanlış olur?', 'İlk köy romanı – Namık Kemal', ['İlk tiyatro – Şinasi', 'İlk yerli roman – Şemsettin Sami', 'İlk tarihî roman – Namık Kemal'], 'İlk köy romanı Karabibik\'tir ve Nabizade Nazım\'a aittir; diğer eşleştirmeler doğrudur.'),
  ('Tanzimat döneminin "geçiş dönemi" niteliğini en açık biçimde gösteren örnek hangisidir?', 'Namık Kemal\'in hürriyet kavramını kaside biçiminde işlemesi', ['Ömer Seyfettin\'in Yeni Lisan\'ı yazması', 'Halit Ziya\'nın Aşk-ı Memnu\'yu yazması', 'Ahmet Haşim\'in Göl Saatleri\'ni sembolist anlayışla yayımlaması'], 'Yeni bir kavramın (hürriyet) geleneksel bir nazım biçimiyle (kaside) işlenmesi, eski ile yeninin bir arada bulunduğu geçiş dönemini yansıtır.'),
  ('Türk edebiyatında mensur şiirin ilk örnekleri sayılan "Mensur Şiirler" ve "Mezardan Sesler" adlı eserlerin yazarı kimdir?', 'Halit Ziya Uşaklıgil', ['Mehmet Rauf', 'Hüseyin Cahit Yalçın', 'Ahmet Haşim'], 'Halit Ziya bu eserlerle mensur şiirin ilk örneklerini vermiş, türü Servet-i Fünun\'da yaygınlaştırmıştır.'),
  ('Halit Ziya\'nın Aşk-ı Memnu romanında Adnan Bey\'in kızı Nihal\'in bakımıyla ilgilenen yabancı mürebbiye kimdir?', 'Matmazel de Courton', ['Anjel', 'Matmazel Blanche', 'Madam Josefino ve kızı Mari'], 'Matmazel de Courton, Nihal\'i yetiştiren Fransız mürebbiyedir; Anjel ise Hüseyin Rahmi\'nin Mürebbiye romanının kahramanıdır.'),
  ('Tevfik Fikret\'in şiirinde kullandığı biçimler için hangisi yanlıştır?', 'Bütün şiirlerini hece ölçüsüyle yazmıştır.', ['Serbest müstezat biçimini kullanmıştır.', 'Sone ve terza rima gibi Batılı biçimleri denemiştir.', 'Aruzu Türkçeye başarıyla uygulamıştır.'], 'Fikret aruzla yazmıştır; yalnız Şermin\'deki gibi çocuk şiirlerinde dili sadeleştirmiş, hece ölçüsünü ise yok denecek kadar az kullanmıştır.'),
  ('Türk tiyatrosunun kurumsallaşmasında önemli bir adım olan ve 1914\'te İstanbul\'da kurulan tiyatro okulu ve topluluğu hangisidir?', 'Darülbedayi', ['Gedikpaşa Tiyatrosu', 'Osmanlı Tiyatrosu', 'Saray Tiyatrosu'], 'Darülbedayi, Fransız tiyatro adamı André Antoine\'ın danışmanlığında kurulmuş; bugünkü İstanbul Şehir Tiyatroları\'nın temelini oluşturmuştur.'),
  ('Türk tiyatro tarihinde sahneye çıkan ilk Müslüman Türk kadın oyuncu kimdir?', 'Afife Jale', ['Halide Edip', 'Fatma Aliye', 'Müfide Ferit'], 'Afife Jale, 1920\'de Darülbedayi\'de Hüseyin Suat\'ın Yamalar oyununda sahneye çıkmıştır.'),
  ('Musahipzade Celal\'in oyunlarının en belirgin özelliği hangisidir?', 'Eski İstanbul hayatını ve Osmanlı törelerini mizahi bir dille sahneye taşıması', ['Yalnız Batılı mitolojik konuları işleyip Yunan tragedyalarını Türkçeye uyarlaması', 'Oyunlarını sembolist şiir biçiminde yazması', 'Köy hayatını trajik bir dille anlatması'], 'İstanbul Efendisi, Lale Devri, Aynaroz Kadısı gibi oyunlarda Musahipzade, eski İstanbul ve Osmanlı toplumunu güldürü yoluyla yansıtır.'),
  ('Peyami Safa\'nın Mütareke yıllarında İstanbul\'da Batı özentisi genç kızları eleştirdiği ilk romanlarından biri hangisidir?', 'Sözde Kızlar', ['Fatih-Harbiye', 'Yalnızız', 'Matmazel Noraliya\'nın Koltuğu'], 'Sözde Kızlar (1922), işgal yıllarında yozlaşan İstanbul sosyetesini ve alafranga genç kızları eleştirir.'),
  ('Peyami Safa\'nın polisiye ve macera türündeki eserlerinde kullandığı takma ad hangisidir?', 'Server Bedi', ['Kirpi', 'Tiryaki', 'Aka Gündüz'], 'Peyami Safa, Cingöz Recai dizisi gibi popüler eserlerini Server Bedi takma adıyla yayımlamıştır.'),
  ('Halit Ziya\'nın Mai ve Siyah romanında Ahmet Cemil\'in kendisine örnek aldığı, ancak yozlaşmış bir edebiyatçı olarak çizilen kişi kimdir?', 'Raci', ['Hüseyin Nazmi', 'Vehbi Efendi', 'Behlül'], 'Raci, edebiyat çevresinde Ahmet Cemil\'i yanıltan, sonunda bunalıma düşen dekadan bir şairdir; Hüseyin Nazmi ise onun dürüst dostudur.'),
  ('Mai ve Siyah\'ta Ahmet Cemil\'in kız kardeşi İkbal\'in evlendiği ve onu mutsuz eden kişi kimdir?', 'Vehbi Efendi', ['Raci', 'Hüseyin Nazmi', 'Behlül'], 'İkbal, Ahmet Cemil\'in seçtiği Vehbi Efendi ile evlenir; Vehbi\'nin kötü davranışları İkbal\'in yıkımına yol açar.'),
  ('Servet-i Fünun romancılarının kahramanları için aşağıdakilerden hangisi en uygun genellemedir?', 'Çoğunlukla aydın, duyarlı, hayal ile gerçek arasında bunalan kişilerdir.', ['Çoğunlukla Anadolu köylerinde yaşayan, toprağına bağlı köylülerdir.', 'Çoğunlukla savaş kahramanı askerlerdir.', 'Çoğunlukla tarihî hükümdarlardır.'], 'Ahmet Cemil, Necip, Ömer Behiç gibi kahramanlar aydın, hassas, çoğu kez hayal kırıklığına uğrayan bireylerdir.'),
  ('Servet-i Fünun\'da sık rastlanan "kaçış" temasına aşağıdakilerden hangisi örnek gösterilebilir?', 'Tevfik Fikret\'in hayal ettiği uzak ve huzurlu bir ülkeye sığınma özlemi', ['Mehmet Akif\'in Çanakkale Şehitlerine şiiri', 'Ömer Seyfettin\'in Balkan Savaşı\'nı anlatan gerçekçi hikâyeleri', 'Ziya Gökalp\'in Türkçülük programı'], 'Servet-i Fünun sanatçıları baskıdan kaçmak için hayali ülkelere, doğaya ya da uzak yerlere sığınma özlemini işlemiştir.'),
  ('Servet-i Fünun ile Tanzimat ikinci kuşağı arasındaki bağı en iyi gösteren durum hangisidir?', 'Recaizade\'nin "sanat için sanat" anlayışının Servet-i Fünun\'da gelişerek sürmesi', ['Namık Kemal\'in topluluğun başkanı olması', 'Ziya Paşa\'nın Servet-i Fünun dergisini kurup yönetmesi ve genç şairleri yetiştirmesi', 'Şinasi\'nin Servet-i Fünun\'da şiir yayımlaması'], 'Recaizade ve Hamit\'in bireyci, sanatı önceleyen anlayışı Servet-i Fünun\'a miras kalmış; Recaizade topluluğun hazırlayıcısı olmuştur.'),
  ('Bir öğrenci Servet-i Fünun şiirinin sone örneğini incelemek istese aşağıdakilerden hangisi bu amaca en uygun olur?', 'On dört dizeden oluşan, iki dörtlük ve iki üçlükle kurulmuş bir şiir', ['Beyitlerle yazılmış, aynı redifle biten bir gazel', 'Mani biçiminde yazılmış dört dizelik bir şiir', 'Dörtlüklerden oluşan, halk ezgisine uygun, hece ölçüsüyle yazılmış bir koşma'], 'Sone, iki dörtlük ve iki üçlükten oluşan on dört dizelik Batılı bir biçimdir; Servet-i Fünun şairleri bu biçimi denemiştir.'),
  ('Mehmet Akif\'in Safahat\'ında "Hakkın Sesleri" kitabının ayırıcı özelliği hangisidir?', 'Şiirlerin her birinin bir ayet ya da hadisle başlaması', ['Bütün şiirlerin hece ölçüsüyle yazılması', 'Kitabın yalnız mensur şiirlerden oluşması', 'Şiirlerin Çanakkale Savaşı\'nı ve cephedeki askerlerin hayatını anlatması'], 'Hakkın Sesleri\'nde Akif, her şiiri bir ayetle açarak Balkan Savaşı yıllarında İslam toplumunun durumunu yorumlar.'),
  ('Mehmet Akif\'in şiir anlayışında "hayatta görmediğim bir şeyi yazmam" yaklaşımının yansıması hangisidir?', 'Gözleme dayalı gerçekçi bir şiir yazması', ['Hayali ülkeleri anlatması', 'Mitolojik konuları işlemesi', 'Anlamı kapalı, musikiye dayalı sembolist şiirler yazması'], 'Akif, şiirlerini gözlemlediği toplumsal gerçeklere dayandırmış; bu yönüyle gerçekçi bir şairdir.'),
  ('Mehmet Akif\'in Birinci Dünya Savaşı sırasında Almanya\'ya yaptığı yolculuğun izlenimlerini anlatan uzun şiiri Safahat\'ın hangi kitabında yer alır?', 'Hatıralar', ['Asım', 'Gölgeler', 'Hakkın Sesleri'], 'Berlin Hatıraları adlı bu şiir, Safahat\'ın beşinci kitabı olan Hatıralar\'da yer alır.'),
  ('Mehmet Akif\'in şiirinde konuşma dilini ve diyalogları sıkça kullanması, onun manzumelerine hangi niteliği kazandırır?', 'Tiyatro sahnesi gibi canlı ve dramatik bir anlatım', ['Destansı ve olağanüstü bir anlatım', 'Kapalı, sembolik ve çağrışıma dayalı bir anlatım', 'Soyut ve felsefi bir anlatım'], 'Mahalle Kahvesi gibi şiirlerde kişiler kendi ağızlarıyla konuşturulur; bu, manzumelere sahne gibi canlılık verir.'),
  ('Ahmet Haşim\'in "O Belde" şiirinde sözü edilen belde için en doğru yorum hangisidir?', 'Şairin gerçek dünyadan kaçıp sığındığı hayalî bir ülke', ['İstanbul\'un bir semti', 'Doğduğu Bağdat şehri ve Dicle kıyıları', 'Sürgüne gönderildiği bir kasaba'], 'O Belde, gerçek dünyanın çirkinliğinden kaçıp sığınılan, ancak hayalde var olan ideal bir ülkedir; Servet-i Fünun\'daki kaçış teması burada da görülür.'),
  ('"Yorgun gözümün halkalarında / Güller gibi fecr oldu nümâyân" dizelerinde Ahmet Haşim\'in kullandığı imge türü için ne söylenebilir?', 'Renk ve ışıkla kurulan izlenimci bir tablo', ['Bir savaşın destansı tasviri', 'Somut bir olayın gerçekçi ve ayrıntılı anlatımı', 'Tasavvufi bir öğüt'], 'Bir Günün Sonunda Arzu\'dan alınan dizelerde şafak, güllerin rengiyle birleştirilerek izlenimci ve renkli bir imge kurulmuştur.'),
  ('Ahmet Haşim\'in düzyazılarında öne çıkan özellik hangisidir?', 'İnce bir ironi ve zarif bir üslupla toplumu eleştirmesi', ['Yalnız siyasi propaganda yapması', 'Ağır bir öğreticilik ve sürekli ahlak dersi vermesi', 'Teknik bilgilere dayalı bilimsel bir dil kullanması'], 'Haşim\'in Bize Göre ve Gurabahane-i Laklakan\'daki yazıları, nüktedan ve ironik üslubuyla dikkat çeker.'),
  ('Yahya Kemal\'in "Açık Deniz" şiirinde dile getirdiği duygu hangisidir?', 'Atalarının Asya\'dan gelişini hatırlayıp uçsuz bucaksız bir denize duyduğu özlem', ['Bir sevgiliye duyulan kıskançlık', 'İstanbul\'daki bir semte ve oradaki eski konaklara duyduğu bağlılık', 'Köydeki çocukluk anıları'], 'Açık Deniz\'de şair, akınlarla gelen atalarının ruhunu kendinde duyar ve bu ruh ona dar ufuklardan kaçıp açık denize kavuşma özlemi verir.'),
  ('Yahya Kemal\'in şiirlerinde kullandığı dil için hangisi en doğrudur?', 'İstanbul Türkçesinin zarif ve ahenkli bir kullanımı', ['Öz Türkçe kelimelerle sınırlı bir dil', 'Yöresel ağız özelliklerinin ve halk deyişlerinin yoğun kullanımı', 'Fransızca kelimelerle dolu bir dil'], 'Yahya Kemal, İstanbul\'un konuşulan Türkçesini aruzun ahengiyle birleştirmiştir; eski şiire yaklaştığı eserlerinde ise eski kelimelere de yer verir.'),
  ('Yahya Kemal\'in Paris yıllarından dönüşünde savunduğu ve Yunan-Latin kültürüne dayanan kısa ömürlü akım hangisidir?', 'Nev-Yunanilik', ['Hececilik', 'Garipçilik', 'Yeni Lisan ve Millî Edebiyat'], 'Nev-Yunanilik, Türk edebiyatını eski Yunan kültürüyle besleme düşüncesidir; Yahya Kemal ve Yakup Kadri bir süre bu düşünceyi savunmuştur.'),
  ('Yahya Kemal\'in Millî Edebiyat ile ilişkisi için en doğru yargı hangisidir?', 'Millî duyarlılık taşısa da hece yerine aruzu seçerek kendine özgü bir yol izlemiştir.', ['Millî Edebiyat\'ın kurucusu olup Yeni Lisan\'ı yazmıştır.', 'Millî Edebiyat\'a karşı Servet-i Fünun\'u savunmuştur.', 'Hiçbir millî temaya şiirlerinde yer vermeyip yalnız aşkı ve doğayı işlemiştir.'], 'Yahya Kemal millî tarihe ve kültüre bağlı bir şiir yazmış, ancak Millî Edebiyat\'ın hece akımına katılmamıştır.'),
  ('Halide Edip\'in Vurun Kahpeye romanında öğretmen Aliye\'nin trajik sonu hangi düşünceyi vurgular?', 'Bağnazlık ve iş birlikçiliğin Millî Mücadele\'ye verdiği zarar', ['Kadınların eğitim görmemesi gerektiği', 'Şehir hayatının köyden üstün olduğu ve köylünün okumaya ihtiyacı olmadığı', 'Savaşın her zaman gereksiz olduğu'], 'Aliye, yobaz ve iş birlikçi Hacı Fettah gibi kişilerin kışkırtmasıyla linç edilir; roman bağnazlığı ve iş birlikçiliği eleştirir.'),
  ('Reşat Nuri\'nin Çalıkuşu romanının kurgusunda Feride\'nin hatıra defteri hangi işlevi görür?', 'Olayların Feride\'nin ağzından ve iç dünyasıyla birlikte aktarılmasını sağlar.', ['Romanı bir tiyatro metnine dönüştürür.', 'Romanın tarihî belgelere ve arşiv kayıtlarına dayanmasını sağlar.', 'Olayların tümünü Kamran\'ın gözünden anlatır.'], 'Çalıkuşu büyük ölçüde Feride\'nin hatıra defterine dayanır; bu, birinci kişi anlatımla okura kahramanın duygularını doğrudan verir.'),
  ('Tanzimat ve Servet-i Fünun romanlarından oluşan bir listede romanlar yazarlarıyla birlikte verilmiştir. Hangi romanın yazarı yanlış gösterilmiştir?', 'Eylül – Halit Ziya Uşaklıgil', ['Sergüzeşt – Sami Paşazade Sezai', 'Karabibik – Nabizade Nazım', 'Muhadarat – Fatma Aliye'], 'Eylül, Mehmet Rauf\'un romanıdır; Halit Ziya\'nın romanları arasında Mai ve Siyah, Aşk-ı Memnu ve Kırık Hayatlar bulunur.'),
  ('Bir kütüphane görevlisi şiir kitaplarını şairlerine göre raflara diziyor. Hangi kitabı yanlış şairin rafına koymuştur?', 'Göl Saatleri – Yahya Kemal Beyatlı', ['Rübab-ı Şikeste – Tevfik Fikret Bey', 'Safahat – Mehmet Akif Ersoy', 'Kızıl Elma – Ziya Gökalp'], 'Göl Saatleri, Ahmet Haşim\'in ilk şiir kitabıdır; Yahya Kemal\'in kitapları ölümünden sonra yayımlanmıştır.'),
  ('Romanlarla kahramanlarını gösteren aşağıdaki çiftlerin hangisinde bir hata yapılmıştır?', 'Ahmet Celal – Kiralık Konak', ['Feride – Çalıkuşu', 'Bihruz Bey – Araba Sevdası', 'Dilber – Sami Paşazade\'nin Sergüzeşt\'i'], 'Ahmet Celal, Yakup Kadri\'nin Yaban romanının kahramanıdır; Kiralık Konak\'ın kişileri arasında Naim Efendi, Seniha ve Hakkı Celis vardır.'),
  ('Bir öğrenci Türk edebiyatında köy ve Anadolu temasının gelişimini incelemek için eserleri kronolojik olarak okumak istiyor. Aşağıdakilerden hangisi doğru bir sıralamadır?', 'Karabibik → Memleket Hikâyeleri → Yaban', ['Yaban → Karabibik → Memleket Hikâyeleri', 'Memleket Hikâyeleri → Yaban → Karabibik', 'Yaban → Memleket Hikâyeleri → Karabibik'], 'Karabibik 1890\'da, Memleket Hikâyeleri 1919\'da, Yaban ise 1932\'de yayımlanmıştır.'),
  ('Aşağıdaki şair-unvan eşleştirmelerinden hangisi yanlıştır?', 'Ahmet Mithat – Şair-i Âzam', ['Namık Kemal – Vatan Şairi', 'Mehmet Emin – Millî Şair', 'Abdülhak Hamit – Şair-i Âzam'], '"Şair-i Âzam" Abdülhak Hamit\'in unvanıdır; Ahmet Mithat ise "Hâce-i Evvel" olarak anılır.'),
  ('Hece ölçüsünün Türk şiirinde yeniden ön plana çıkışında aşağıdakilerden hangisinin payı en azdır?', 'Cenap Şahabettin', ['Mehmet Emin Yurdakul', 'Ziya Gökalp', 'Beş Hececiler'], 'Cenap Şahabettin aruzla yazan bir Servet-i Fünun şairidir; heceyi Mehmet Emin başlatmış, Gökalp ve Beş Hececiler yaygınlaştırmıştır.'),
  ('Namık Kemal\'in Celâleddin Harzemşah adlı oyununda işlenen tarihî olay hangisidir?', 'Harezmşah Celaleddin\'in Moğol istilasına karşı direnişi', ['Osmanlı ordusunun İstanbul\'u kuşatması ve şehrin fethedilmesi', 'Endülüs Emevîlerinin çöküşü', 'Kırım hanlarının Rus savaşları'], 'Oyun, Harezmşahlar hükümdarı Celaleddin\'in Cengiz Han\'ın orduları karşısındaki mücadelesini işler.'),
  ('Ahmet Mithat\'ın "Paris\'te Bir Türk" ve "Jön Türk" gibi eserlerinde sıkça işlediği karşılaştırma hangisidir?', 'Doğu ile Batı yaşayışı ve değerleri', ['Asker ile sivil hayatı', 'Köy ile kasaba hayatı arasındaki ekonomik farklar', 'Zengin ile yoksul köylü'], 'Ahmet Mithat, Batı\'nın bilim ve tekniğinin alınıp ahlak ve geleneklerin korunması gerektiği düşüncesini Doğu-Batı karşılaştırmalarıyla işler.'),
  ('Hüseyin Rahmi Gürpınar\'ın ilk romanı olan ve alafranga bir züppeyi konu edinen eseri hangisidir?', 'Şık', ['Mürebbiye', 'Gulyabani', 'Cadı'], 'Şık (1889), Hüseyin Rahmi\'nin alafranga özentisini alaya aldığı ilk romanıdır.'),
  ('Hüseyin Rahmi Gürpınar\'ın romanlarında kişilerin kendi ağızlarıyla konuşturulması ve İstanbul semt ağızlarının yansıtılması neyi amaçlar?', 'Gerçekçiliği ve canlılığı artırmayı', ['Romanı şiirsel kılmayı', 'Okuru şaşırtmak için dili bozmayı', 'Romanı yabancı okurlara uygun hâle getirmeyi'], 'Hüseyin Rahmi, kişileri sosyal çevrelerinin diliyle konuşturarak gerçekçi ve canlı bir anlatım elde eder.'),
  ('Reşat Nuri Güntekin\'in Maarif Müfettişliği görevi eserlerine en çok hangi yönden yansımıştır?', 'Anadolu kasabalarını ve insanlarını yakından tanıyıp romanlarına taşımasıyla', ['Yalnız İstanbul\'un sosyetesini, yalılarını ve konak hayatını anlatmasıyla', 'Tarihî romanlara yönelmesiyle', 'Şiire ağırlık vermesiyle'], 'Müfettiş olarak dolaştığı Anadolu, Reşat Nuri\'nin roman ve gezi yazılarının başlıca kaynağı olmuştur.'),
  ('Yakup Kadri\'nin Bir Sürgün romanında konu edinilen durum hangisidir?', 'II. Abdülhamit döneminde Paris\'e kaçan genç bir doktorun yalnızlığı', ['Kurtuluş Savaşı\'nda bir Anadolu köyünün işgalcilere karşı direnişi', 'Tanzimat yıllarında bir paşanın sürgünü', 'Cumhuriyet\'in ilk yıllarında Ankara\'da yaşayan bir memurun hayatı'], 'Bir Sürgün\'de Doktor Hikmet, istibdattan kaçıp gittiği Paris\'te yabancılık ve yalnızlık yaşar.'),
  ('Yakup Kadri Karaosmanoğlu\'nun romanlarında olayların genellikle tarihî ve toplumsal bir dönemle sıkı bağ içinde verilmesi, onun hangi roman türünde öne çıktığını gösterir?', 'Tezli ve toplumsal roman', ['Bilimkurgu ve ütopya romanı', 'Polisiye roman', 'Fantastik roman'], 'Yakup Kadri belli bir düşünceyi savunan, toplumun dönüşümünü işleyen tezli romanlar yazmıştır.'),
  ('Halide Edip Adıvar\'ın 1909 sonrası yazdığı ilk romanlarında hangi tema baskındır?', 'Aydın kadınların duygusal ve ruhsal dünyası', ['Anadolu köylüsünün ekonomik sorunları ve toprak kavgaları', 'Osmanlı fetihleri', 'Bilimsel buluşlar'], 'Handan, Seviye Talip, Raik\'in Annesi gibi ilk romanlarında Halide Edip kadın psikolojisini ve aşkı işler.'),
  ('Ömer Seyfettin\'in "Bomba" hikâyesinde işlenen konu hangisidir?', 'Makedonya\'da Bulgar komitacıların faaliyetleri', ['Trablusgarp\'ta İtalyan işgaline karşı direniş ve gönüllüler', 'İstanbul\'da bir yangın', 'Bir köydeki toprak kavgası'], 'Bomba, Balkanlardaki Bulgar çetelerinin vahşetini ve kendi halklarına bile zarar veren tutumlarını anlatır.'),
  ('Ömer Seyfettin\'in hikâyelerinde sonun genellikle şaşırtıcı bir olayla bağlanması, okur üzerinde nasıl bir etki bırakmayı amaçlar?', 'Merakı sürdürüp çarpıcı bir son etkisi yaratmayı', ['Okuru sıkıp metni bırakmasını sağlamayı', 'Olayı belirsiz bırakıp okura hiçbir ipucu vermemeyi', 'Okura uzun bir öğüt vermeyi'], 'Olay hikâyesinin tipik özelliği olan beklenmedik son, Ömer Seyfettin\'de okurun ilgisini metin boyunca canlı tutar.'),
  ('Ziya Gökalp\'in "Kızıl Elma" adlı eseri için hangisi doğrudur?', 'Türk destan ve efsanelerinden de yararlanan bir şiir kitabıdır.', ['Bir köy romanıdır.', 'Divan şairlerinin biyografilerini ve şiirlerinden örnekleri içeren bir tezkiredir.', 'Bir gezi kitabıdır.'], 'Kızıl Elma (1914), Gökalp\'in Türkçülük ülküsünü destan ve masal unsurlarıyla birlikte işlediği şiir kitabıdır.'),
  ('Ali Canip Yöntem\'in Millî Edebiyat hareketindeki yeri için hangisi doğrudur?', 'Genç Kalemler\'i Selanik\'te çıkaran kurucu isimlerden biridir.', ['Servet-i Fünun\'un kurucusudur.', 'Fecr-i Âti beyannamesinin yazarıdır.', 'Tanzimat\'ın ilk yerli romanını yazarak Türk romanını başlatmıştır.'], 'Ali Canip, Ömer Seyfettin ile birlikte Genç Kalemler\'in yayımlanmasında başrolü oynamış; şair ve edebiyat tarihçisidir.'),
  ('Millî Edebiyat döneminin tiyatroya katkısı olarak hangisi gösterilebilir?', 'Darülbedayi\'nin kurulmasıyla tiyatronun kurumsallaşması', ['Şair Evlenmesi\'nin yazılması', 'Gedikpaşa Tiyatrosu\'nun açılması ve Güllü Agop\'un kumpanyayı kurması', 'Ortaoyununun yeniden icat edilmesi'], '1914\'te kurulan Darülbedayi, Millî Edebiyat yıllarında yerli oyunların düzenli olarak sahnelenmesini sağlamıştır.'),
  ('Namık Kemal\'in romanına verdiği "İntibah" (uyanış) adı, olay örgüsünde neye karşılık gelir?', 'Ali Bey\'in yaptığı hataları çok geç fark edip pişmanlık duyması', ['Halkın bir zalime karşı ayaklanması', 'Bir köyün tarıma başlaması', 'Kahramanın uzun bir uykudan uyanıp başka bir çağda kendini bulması'], 'Romanın kahramanı Ali Bey, Mehpeyker\'e kapılarak düştüğü felaketi ancak iş işten geçtikten sonra anlar; "uyanış" bu geç gelen farkındalıktır.'),
  ('Ahmet Mithat\'ın 1870\'te yayımlamaya başladığı, kısa ve öğretici anlatılardan oluşan ilk hikâye denemesi hangisidir?', 'Kıssadan Hisse', ['Letaif-i Rivayat', 'Müşahedat', 'Dürdane Hanım'], 'Kıssadan Hisse, La Fontaine tarzı kısa, ders veren anlatılardan oluşur; daha olgun hikâyeler Letaif-i Rivayat\'ta yer alır.'),
  ('1908\'de II. Meşrutiyet\'in ilanının ardından basın hayatında görülen gelişmenin edebiyata etkisi hangisidir?', 'Sansürün kalkmasıyla çok sayıda gazete ve derginin çıkması, yeni toplulukların doğması', ['Bütün gazetelerin kapatılması', 'Edebiyatın yalnız sarayda yapılır hâle gelmesi', 'Roman yazımının yasaklanması'], 'Meşrutiyet\'in getirdiği görece özgürlük ortamında yüzlerce yayın organı çıktı; Fecr-i Âti ve Genç Kalemler bu ortamda doğdu.'),
  ('Mütareke yıllarında işgal altındaki İstanbul\'daki ahlaki çöküşü eleştiren romanlar hangi seçenekte birlikte verilmiştir?', 'Sodom ve Gomore ve Sözde Kızlar', ['Mai ve Siyah ve Eylül', 'İntibah ve Cezmi', 'Karabibik ve Zehra'], 'Yakup Kadri\'nin Sodom ve Gomore\'si ile Peyami Safa\'nın Sözde Kızlar\'ı Mütareke İstanbul\'unu eleştirir.'),
  ('Ali Ekrem Bolayır\'ın askerlik ve vatan sevgisini işleyen şiirlerini topladığı eser hangisidir?', 'Ordu\'nun Defteri', ['Haluk\'un Defteri', 'Kızıl Elma', 'Türk Sazı'], 'Ordu\'nun Defteri, Ali Ekrem\'in orduyu ve askeri konu alan şiirlerini içerir; babası Namık Kemal\'in vatan sevgisini sürdürür.'),
  ('Mehmet Emin Yurdakul\'un Birinci Dünya Savaşı yıllarında yayımladığı ve millî duyguları işleyen şiir kitabı hangisidir?', 'Türk Sazı', ['Kızıl Elma', 'Safahat', 'Han Duvarları'], 'Türk Sazı (1914), Mehmet Emin\'in hece ölçüsüyle millî duyguları dile getirdiği şiirlerinden oluşur.'),
  ('Recaizade Mahmut Ekrem\'in şiirlerinde ölüm temasının ağırlık kazanmasının biyografik nedeni nedir?', 'Çocuklarını ve yakınlarını genç yaşta kaybetmesi', ['Savaşta yaralanması', 'Uzun süre sürgünde yaşaması', 'Görme yetisini kaybetmesi'], 'Recaizade, oğlu Nijad başta olmak üzere birçok yakınını kaybetmiş; bu kayıplar şiirine hüzün ve ölüm teması olarak yansımıştır.'),
  ('Tevfik Fikret\'in Servet-i Fünun\'un kapanmasından sonra toplumsal şiire yönelmesi, onun sanat anlayışında nasıl bir değişime işaret eder?', 'Bireysel duygulardan toplumun ve insanlığın sorunlarına doğru bir genişleme', ['Toplumsal konulardan aşk şiirine dönüş', 'Aruzdan heceye geçiş', 'Şiirden tamamen vazgeçip roman yazmaya başlama'], 'Fikret 1901 sonrası Sis, Han-ı Yağma, Haluk\'un Defteri gibi şiirlerle toplumsal ve ahlaki sorunları işleyen bir şair kimliği kazanır.'),
  ('Halit Ziya\'nın Aşk-ı Memnu\'yu yazdığı dönemde Türk romanının ulaştığı düzeyi en iyi açıklayan yargı hangisidir?', 'Batılı roman tekniğinin Türk romanında olgunluğa ulaşması', ['Romanın henüz yalnız çeviri olarak var olması', 'Romanın tesadüflerle dolu, acemi bir tür olarak kalması', 'Romanın tamamen manzum yazılması'], 'Aşk-ı Memnu, kurgu, tasvir ve karakter çözümlemesi bakımından Batılı romanın Türk edebiyatındaki ilk olgun örneklerinden kabul edilir.'),
  ('Ahmet Haşim ile Cenap Şahabettin\'in şiir anlayışları arasındaki ortak nokta hangisidir?', 'İkisinin de sembolizmden etkilenip şiirde musikiyi önemsemesi', ['İkisinin de hece ölçüsüyle yazması', 'İkisinin de toplumsal şiiri savunması', 'İkisinin de Millî Edebiyat\'ın kurucusu olması'], 'Cenap Servet-i Fünun\'da, Haşim Fecr-i Âti\'de sembolist etkilerle şiirde ahenk ve çağrışıma önem vermiştir.'),
  ('"Bu şair Diyarbakır\'da doğmuş, Malta\'ya sürgün edilmiş, Türkçülüğün Esasları\'nı yazmış ve dil üzerine \'Lisan\' şiirini kaleme almıştır." Sözü edilen kişi kimdir?', 'Ziya Gökalp', ['Süleyman Nazif', 'Mehmet Emin Yurdakul', 'Faik Ali Ozansoy'], 'Bu bilgiler Ziya Gökalp\'e aittir; Süleyman Nazif de Diyarbakırlıdır ve Malta\'ya sürülmüştür ancak Türkçülüğün Esasları onun değildir.'),
  ('Şinasi\'nin Şair Evlenmesi\'nde mahalle imamı Batak Efendi\'nin para karşılığında sorunu çözmesi, oyunda hangi toplumsal aksaklığa işaret eder?', 'Din adamı kimliğinin çıkar için kullanılmasına ve rüşvete', ['Askerlik sisteminin bozukluğuna ve kura usulünün adaletsizliğine', 'Ticarette tekelleşmeye', 'Okulların yetersizliğine'], 'Batak Efendi\'nin rüşvetle tutum değiştirmesi, görücü usulünün yanında din adamlarının bir kısmındaki çıkarcılığı da eleştirir.'),
  ('Ahmet Mithat\'ın 1875\'te yayımlanan ve alafranga tipi eleştirdiği romanında kendi görüşlerini hangi kahramana yüklediği söylenebilir?', 'Rakım Efendi', ['Felatun Bey', 'Mister Ziklas', 'Canan'], 'Çalışkan, okuyan ve dengeli bir Batılılaşmayı temsil eden Rakım Efendi, yazarın ideal insan tipidir; Ahmet Mithat\'ın kendi hayatından izler de taşır.'),
  ('Sami Paşazade Sezai\'nin Sergüzeşt\'inde Dilber\'in Mısır\'a satılmasına yol açan kişi kimdir?', 'Celal Bey\'in annesi', ['Celal Bey\'in kendisi', 'Dilber\'in babası', 'Bir İngiliz tüccar'], 'Oğlu Celal Bey\'in Dilber\'e âşık olmasını istemeyen anne, Dilber\'i başka bir esirciye sattırır; bu satış Dilber\'in Mısır\'a götürülmesine yol açar.'),
  ('Recaizade\'nin Araba Sevdası\'nda Bihruz Bey\'in yanlış Batılılaşmasını en iyi gösteren davranış hangisidir?', 'Fransızca kelimeleri yerli yersiz ve yanlış kullanarak konuşması', ['Babasının işini büyütüp zengin olması', 'Çok kitap okuyup Batı edebiyatını derinlemesine öğrenmesi ve bilgin olması', 'Köyüne dönüp tarım yapması'], 'Bihruz Bey, Fransızcayı yarım yamalak bilir ve Türkçe konuşurken araya sürekli yanlış Fransızca kelimeler katar; bu, yüzeysel Batılılaşmanın gülünç bir göstergesidir.'),
  ('Mehmet Rauf\'un Eylül romanında olayların çoğunun bir yalı ve bir köşk arasında geçmesi, Servet-i Fünun romanının hangi özelliğini yansıtır?', 'Dar ve kapalı mekânların tercih edilmesi', ['Anadolu köylerinin ayrıntılı tasviri', 'Savaş alanlarının ön plana çıkması', 'Tarihî mekânların yeniden canlandırılması'], 'Servet-i Fünun romanında olaylar çoğunlukla İstanbul\'un seçkin çevrelerine ait yalı, köşk ve konak gibi kapalı mekânlarda geçer.'),
  ('Fecr-i Âti\'nin bir topluluk olarak kısa ömürlü olmasının sonucunda üyelerinin yönelimi için hangisi doğrudur?', 'Bir kısmı Millî Edebiyat\'a geçmiş, bir kısmı bireysel çizgisini sürdürmüştür.', ['Topluca Divan şiirine dönüp gazel ve kaside yazmaya başlamışlardır, bu dönüş uzun sürmüştür.', 'Birlikte Servet-i Fünun\'u yeniden kurmuşlardır.', 'Edebiyatı bırakıp ticarete ve siyasete atılmışlardır.'], 'Yakup Kadri, Refik Halit gibi isimler Millî Edebiyat çizgisine yaklaşırken Ahmet Haşim kendi sembolist yolunda ilerlemiştir.'),
  ('Ziya Gökalp\'in Altın Işık\'ta masal ve destanları yeniden yazmasının amacı nedir?', 'Millî kültürün kaynaklarını sade bir dille yeni kuşaklara ulaştırmak', ['Yabancı masalları Türkçeye çevirip Batı kültürünü tanıtmak', 'Divan şiirini yeniden canlandırmak', 'Bilimsel bir sözlük hazırlamak'], 'Gökalp halk kültürünü millî kimliğin temeli sayar; Altın Işık bu kültürü sade Türkçeyle yeniden sunar.'),
  ('Mehmet Akif\'in Safahat\'ının ilk kitabındaki şiirlerin genel karakteri için hangisi doğrudur?', 'İstanbul\'un yoksul insanlarını anlatan gerçekçi manzum hikâyelerin ağırlıkta olması', ['Bütünüyle tasavvufi gazellerden oluşması', 'Yalnız Çanakkale Savaşı\'nı işlemesi', 'Mısır\'daki hayatını, yalnızlığını ve yurt özlemini anlatan içe dönük şiirlerin ağırlıkta olması'], 'Safahat\'ın ilk kitabında Küfe, Hasta, Seyfi Baba gibi gözleme dayalı manzum hikâyeler öne çıkar.'),
  ('Mehmet Akif\'in "Fatih Kürsüsünde" adlı kitabında öne çıkan konu hangisidir?', 'Bir vaizin ağzından toplumun tembelliğini ve geri kalmışlığını eleştirmesi', ['Berlin yolculuğunun izlenimleri ve Almanların çalışkanlığına duyulan hayranlık', 'Çocuk şiirleri', 'Mısır\'daki yalnızlık duyguları'], 'Fatih Kürsüsünde, Fatih Camii\'nde konuşan bir vaizin ağzından çalışmaya, birliğe ve azme çağrı yapar.'),
  ('Halide Edip\'in Ateşten Gömlek romanının başkahramanlarından Ayşe\'nin taşıdığı sembolik anlam nedir?', 'Millî Mücadele\'de acılar çekip direnen Anadolu kadınını temsil etmesi', ['Saray kadınlarının entrikalarını temsil etmesi', 'Batı özentisi, sosyete hayatına düşkün İstanbul kadınını temsil etmesi', 'Kaderine boyun eğen edilgen bir tipi temsil etmesi'], 'İzmir\'in işgalinde ailesini kaybeden Ayşe, Millî Mücadele\'ye katılan fedakâr Türk kadınının simgesidir.'),
  ('Yakup Kadri\'nin Nur Baba romanının yayımlandığında tepki çekmesinin nedeni nedir?', 'Bir tarikat çevresindeki yozlaşmayı açıkça eleştirmesi', ['Bir padişahı övmesi', 'Hece ölçüsüyle yazılmış olması', 'Bütünüyle Fransızca yazılmış olması ve Türk okuruna yabancı gelmesi'], 'Nur Baba, Bektaşi tekkesindeki ahlaki çöküşü sert bir dille anlattığı için o çevrelerin tepkisini çekmiştir.'),
  ('Refik Halit Karay\'ın üslubu için en belirgin özellik hangisidir?', 'Canlı, akıcı ve tasvir gücü yüksek bir Türkçe kullanması', ['Yalnız şiirsel ve kapalı bir dil kullanması', 'Ağır, süslü ve tamlamalarla dolu bir Osmanlıca kullanması', 'Diyaloglardan tamamen kaçınması'], 'Refik Halit, Türkçenin en usta nesir yazarlarından sayılır; tasvirleri canlı, dili akıcı ve renklidir.'),
  ('Bir araştırmacı Tanzimat ile Servet-i Fünun arasındaki "köprü" konumundaki sanatçıları incelemek istiyor. Aşağıdakilerden hangisi bu araştırma için en uygun isimdir?', 'Recaizade Mahmut Ekrem', ['Ziya Gökalp', 'Mehmet Emin Yurdakul', 'Faruk Nafiz Çamlıbel'], 'Recaizade, Tanzimat ikinci kuşağında yer alıp Servet-i Fünun\'un hazırlayıcısı olduğu için iki dönem arasında köprü sayılır.'),
];
